(function(){
'use strict';

/* Isi halaman (HTML siap tampil, dibuat dari draf yang disetujui). */
const RF_DATA = {"faqIntro":"<p>Answers to the questions new players ask most often, based on the <strong>Comprehensive Rules 1.03<\/strong> (12 Aug 2026) and on statements by the <strong>Head Judge of Marvel Hero Rush Indonesia<\/strong>. Each answer shows its source and date.<\/p><p class=\"rf-note\">This is a community FAQ by MHR Deck Lab, not an official document. If an official ruling says otherwise, the official ruling wins. Rules change: always check the rules version and date.<\/p>","faq":[{"t":"Getting started","items":[{"id":"F-01","q":"What are the deck building rules?","a":"<ul><li>Your Deck has exactly <strong>50 Characters<\/strong>.<\/li><li>It can use <strong>at most 2 colours<\/strong>.<\/li><li>At most <strong>3 cards with the same Character name<\/strong>.<\/li><li>You also need a <strong>Rush Point Deck of 9 Rush Points<\/strong>. Any Rush Points can be used.<\/li><\/ul>","src":"CR 101.1.b–d, 101.2.b–c."},{"id":"F-02","q":"How do I win?","a":"<p>You win as soon as either of these happens:<\/p><ul><li>you have <strong>9 Rush Points in your Timeline<\/strong>, or<\/li><li>your opponent's <strong>Deck has 0 cards<\/strong>.<\/li><\/ul><p>A card effect can also declare a winner.<\/p>","src":"CR 103.1.a–c."},{"id":"F-03","q":"How does the game start? Can I redraw my starting hand (mulligan)?","a":"<ul><li>Each player draws <strong>6 cards<\/strong>.<\/li><li>Each player may <strong>mulligan once<\/strong>. The first player decides first, then the second player.<\/li><li>Choose <strong>how many<\/strong> of your 6 cards you want to replace: from 1 up to all 6. You can also keep your hand as it is.<\/li><li>Put the cards you are replacing <strong>on the bottom of your Deck<\/strong> face-down, then <strong>draw the same number<\/strong> from the top so you have 6 cards again. Then <strong>shuffle your Deck<\/strong>.<\/li><li>Example: you replace 2 cards. Put those 2 on the bottom of your Deck, draw 2 from the top, then shuffle.<\/li><\/ul><p>Try it with the <strong>Opening Draw Simulation<\/strong> in the Deck Builder.<\/p>","src":"CR 303.1.d–e."},{"id":"F-04","q":"What is different on the first player's first turn?","a":"<ul><li>The first player can CALL only <strong>once<\/strong> (instead of up to 3 times).<\/li><li>The first player can do <strong>Base Deployment once<\/strong>, as in every turn: place 1 card from the HAND face-down into the BASE, then draw 1 card.<\/li><li>The first player <strong>skips the Battle Phase<\/strong>.<\/li><\/ul>","src":"CR 303.2.a.3.1.2.3, 303.2.a.3.1.1, 303.2.a.4.1."},{"id":"F-05","q":"What can I do in my Action Phase, and how often?","a":"<p>In any order:<\/p><ul><li><strong>Base Deployment<\/strong> — place 1 card from your HAND face-down into your BASE, then draw 1 card. <strong>Once per turn.<\/strong><\/li><li><strong>Action CALL<\/strong> — CALL a Character. <strong>Up to 3 times per turn.<\/strong><\/li><li><strong>BATTLE-BASE MOVE<\/strong> — each Character can move between BATTLE and BASE <strong>once per turn<\/strong>. A Character placed onto the FIELD this turn cannot do this.<\/li><li><strong>Activate<\/strong> ACTI or COUNTER·ACTI effects.<\/li><\/ul>","src":"CR 303.2.a.3.1.1–303.2.a.3.1.4."},{"id":"F-06","q":"Is there a hand size limit?","a":"<p>Yes. In your End Phase, if you have more than <strong>9 cards<\/strong> in your HAND, discard down to 9.<\/p>","src":"CR 303.2.a.6.1.3."}]},{"t":"CALL, BASE and Face-Down Cards","items":[{"id":"F-07","q":"How do I CALL a Lv4 or higher Character? Can the cost come from my HAND?","a":"<ul><li>To CALL a Lv4+ Character, <strong>retreat Characters on your FIELD<\/strong> whose <strong>total Lv equals<\/strong> the Lv of the Character you are calling, then place it from your HAND.<\/li><li>The cost must come from your <strong>FIELD<\/strong> (BATTLE or BASE), not from your HAND.<\/li><li><strong>Face-Down Cards<\/strong> in your BASE can be part of the cost. Each one counts as <strong>Lv1<\/strong>.<\/li><li>Lv3 or lower Characters have no cost.<\/li><\/ul>","src":"CR 301.19.a–b, 301.21.g."},{"id":"F-08","q":"Does the BASE limit of 6 include Face-Down Cards?","a":"<p>Yes. The BASE holds <strong>6 cards in total<\/strong>, Characters and Face-Down Cards together.<\/p>","src":"CR 302.6.a. Head Judge of Marvel Hero Rush Indonesia, 24 Sep 2026."},{"id":"F-09","q":"Is \"placed\" the same as \"called\"? Does a \"when called\" effect trigger if a card is placed by an effect?","a":"<p>No. <strong>CALL<\/strong> is the rule action in CR 301.19: it places a Character from your HAND by paying its cost. An effect that says \"place\" puts a card onto the FIELD without a CALL. So effects that say <strong>\"when this card enters the field by calling\"<\/strong> do not trigger when the card is placed by an effect (for example by 「Turn The Tide」 Captain America).<\/p>","src":"CR 301.12.a, 301.19. Head Judge of Marvel Hero Rush Indonesia, 14 and 29 Aug 2026."},{"id":"F-10","q":"Can a Character attack on the turn it was called?","a":"<p>Yes. Each Character in your BATTLE gets one attack opportunity each turn, and no rule stops a Character that entered this turn from attacking. The only restriction on new Characters is that they cannot use BATTLE-BASE MOVE this turn. This includes a Character you COUNTER CALL into an empty WING while your FRONT is still attacking: it can attack when the WINGs' turn comes.<\/p>","src":"CR 303.2.a.4.4, 303.2.a.3.1.3.3. Head Judge of Marvel Hero Rush Indonesia, 15 Aug 2026."},{"id":"F-11","q":"If I flip a Face-Down Card face-up, did it \"enter the field\"?","a":"<p>No. Flipping a Face-Down Card face-up is <strong>not<\/strong> placing it onto the FIELD, so \"when this card enters the field\" effects do not trigger. The flipped Character can still use BATTLE-BASE MOVE that turn.<\/p><p><strong>You cannot flip a Face-Down Card just because you want to.<\/strong> No game action lets you do that. A Face-Down Card is turned face-up only when an effect tells you to flip it. Flipping your own Face-Down Card without such an effect is <strong>not legal<\/strong>.<\/p><p><strong>Example:<\/strong> <a class=\"nw-chip rf-chip\" href=\"#c=SP01-061\" data-card=\"SP01-061\"><b>SP01-061<\/b><\/a> 「Spider-Archenemy」 Mr. Negative. Its ACTI【HAND】 can be used on your turn if you have not called a Character and you have as many set cards (Face-Down Cards) as Characters in your BASE. You place Mr. Negative from your HAND onto your WING, and then <em>\"you flip all your cards in BASE\"<\/em>. Your Face-Down Cards are turned face-up <strong>because of this effect<\/strong>:<\/p><ul><li>they did not enter the field, so their \"when this card enters the field\" effects do not trigger;<\/li><li>they can still use BATTLE-BASE MOVE this turn;<\/li><li>Mr. Negative itself was placed onto the FIELD, so its own TRIG (\"when this card enters the field\") does trigger.<\/li><\/ul><p>Without an effect like this, your Face-Down Cards stay face-down.<\/p>","src":"CR 301.22.a–c. Head Judge of Marvel Hero Rush Indonesia, 1 Oct 2026."},{"id":"F-12","q":"Does a Face-Down Card's effect trigger when it is retreated?","a":"<p>No. A Face-Down Card has no effects, and it is still treated as a Face-Down Card while it moves to the RETREAT. Example: a face-down 「Cosmic Legacy」 Silver Surfer retreated as a CALL cost does not trigger.<\/p>","src":"CR 301.21.c, 301.21.h."},{"id":"F-13","q":"How does UNIQUE work?","a":"<ul><li>You can never have two cards with the same name on your FIELD if one of them is UNIQUE. If one is there, another copy cannot enter in any way.<\/li><li>A Face-Down copy that would be flipped stays face-down and is only <strong>revealed<\/strong>.<\/li><li>You <strong>can<\/strong> retreat the copy on your FIELD as the CALL cost of another copy, because the cost is paid before the new card is placed.<\/li><li>UNIQUE cannot be lost, even to effects like Anti-Venom.<\/li><li>UNIQUE is an <strong>AUTO<\/strong> effect, so a UNIQUE Character counts as a card with 【AUTO】 in its effects. Example: <a class=\"nw-chip rf-chip\" href=\"#c=BP01-022\" data-card=\"BP01-022\"><b>BP01-022<\/b><\/a> 「Top Agent」 Black Widow can retreat an opponent's Lv3 or lower UNIQUE Character.<\/li><li><strong>Attached Cards count too.<\/strong> An Attached Card is still a card on your FIELD and keeps its own effects, including UNIQUE. So a UNIQUE card and another card with the same name can never both be on your FIELD, whether each of them is a Character or an Attached Card. A card that would break this cannot be attached, called or placed. Examples:<ul><li><a class=\"nw-chip rf-chip\" href=\"#c=SP01-021\" data-card=\"SP01-021\"><b>SP01-021<\/b><\/a> 「The Web of Destiny」 Spider-Man is on your FIELD. Its effect lets you attach a 【Web】 Character from your HAND, but you cannot choose <a class=\"nw-chip rf-chip\" href=\"#c=SP01-033\" data-card=\"SP01-033\"><b>SP01-033<\/b><\/a> 「Spider-Mentor」 Spider-Man: it has the same name, so it cannot be attached.<\/li><li>「Spider-Mentor」 Spider-Man is attached to one of your Characters. You cannot CALL or place 「The Web of Destiny」 Spider-Man (or any other card named Spider-Man) onto your FIELD while it stays attached.<\/li><\/ul><\/li><\/ul>","src":"CR 305.6.a, 301.22.d, 301.25.k. Head Judge of Marvel Hero Rush Indonesia, 29 Sep, 7, 14 and 17 Oct 2026."}]},{"t":"Attacking","items":[{"id":"F-14","q":"In what order do my Characters attack?","a":"<ul><li>At the start of your Battle Phase you may <strong>rearrange<\/strong> up to 4 Characters in your BATTLE once. This is not a move.<\/li><li>Then you attack in the order <strong>FRONT → WINGs → BACK<\/strong>. If both WINGs have a Character, you choose which WING attacks first.<\/li><li>Each Character has <strong>one<\/strong> attack opportunity per turn. If you choose not to attack with it, that opportunity is lost.<\/li><\/ul>","src":"CR 303.2.a.4.2.1–303.2.a.4.2.2, 303.2.a.4.4, 303.2.a.4.7, 303.2.a.4.9.1."},{"id":"F-15","q":"What can I attack? What is a Weakness?","a":"<ul><li>An attacking Character chooses <strong>1 Character in the opponent's BATTLE<\/strong> or <strong>1 Weakness<\/strong> within its <strong>R<\/strong>.<\/li><li>A <strong>Weakness<\/strong> is an empty BATTLE area.<\/li><li>Distance: your BACK → your WINGs = 1, your WINGs → your FRONT = 1, your FRONT → the opponent's FRONT = 1, their FRONT → their WINGs = 1, their WINGs → their BACK = 1.<\/li><li>A Character with R 0, or with no valid target in range, cannot attack.<\/li><\/ul>","src":"CR 303.2.a.4.3.1.1, 301.20.a, 303.2.a.4.6."},{"id":"F-16","q":"How is a battle decided?","a":"<ul><li><strong>Character vs Character:<\/strong> compare Power. Higher Power wins and the loser is retreated. <strong>Equal Power: both lose<\/strong> and both are retreated. Power is compared, not subtracted.<\/li><li><strong>Character vs Weakness:<\/strong> the attack succeeds and the attacker places the top card of their Rush Point Deck into their Timeline.<\/li><\/ul>","src":"CR 303.2.a.4.3.3.1–303.2.a.4.3.3.2."},{"id":"F-17","q":"My target became invalid (it left, or a COUNTER CALL filled the empty area). What happens?","a":"<ul><li>Once you declare an attack, the battle must go on: you cannot cancel it.<\/li><li>If the target becomes invalid, finish resolving all effects, then <strong>choose a new valid target<\/strong> within R.<\/li><li>If no valid target is left (for example R dropped to 0), the battle ends.<\/li><li>If the attacker leaves the FIELD, the battle ends.<\/li><li>A COUNTER CALL that does not make the target invalid does not cause a retarget.<\/li><\/ul>","src":"CR 303.2.a.4.5, 303.2.a.4.3.1.3–303.2.a.4.3.1.6, 303.2.a.4.3.2.2, 303.2.a.4.3.2.5–303.2.a.4.3.2.6. Head Judge of Marvel Hero Rush Indonesia, 10 Aug, 18 Aug, 3 Sep and 17 Oct 2026."},{"id":"F-18","q":"Do \"when this card attacks\" effects trigger again after a retarget?","a":"<p>No. They trigger when the attack is declared. A retarget only repeats choosing the target, so they do not trigger again. Example: a Character that gives -2000 when it attacks does not give a second -2000 after retargeting.<\/p>","src":"CR 303.2.a.4.3.1.6. Head Judge of Marvel Hero Rush Indonesia, 15–16 Aug 2026."},{"id":"F-19","q":"What if the attacking Character is replaced, or swapped?","a":"<ul><li>If the <strong>attacker<\/strong> is replaced by another Character (not swapped), the first attack ends and the new Character declares a new attack from the start.<\/li><li>A <strong>swap<\/strong> is different: the swapped-in card takes over the other card's state, including \"has attacked\" and \"is attacking\". The Attack Target stays the same, so there is no retarget.<\/li><\/ul>","src":"CR 301.18.b–c, 303.2.a.4.3.2.6. Head Judge of Marvel Hero Rush Indonesia, 13 and 23 Oct 2026."},{"id":"F-20","q":"Does a Character whose attack failed count as \"did not attack\"?","a":"<p>No. A Character that <strong>declared<\/strong> an attack has attacked, even if the attack was countered, lost its target or ended early. Only a Character that never declared an attack \"did not attack\". This matters for cards such as Loki 「God of Story」.<\/p>","src":"CR 303.2.a.4.5. Head Judge of Marvel Hero Rush Indonesia, 18 Aug, 6 Oct and 17 Oct 2026."},{"id":"F-21","q":"How does AIR STRIKE work? Can it be redirected?","a":"<ul><li>A Character with AIR STRIKE may attack the BATTLE area of an opponent's Character <strong>as if it were a Weakness<\/strong>. It may also choose to attack a Character normally.<\/li><li>The attack can still be <strong>redirected<\/strong>, for example by a Character with <strong>BLOCK<\/strong> or by <a class=\"nw-chip rf-chip\" href=\"#c=BP01-067\" data-card=\"BP01-067\"><b>BP01-067<\/b><\/a> 「Hostile Focus」 Winter Soldier. The attacker must then battle the new target.<\/li><li>The rulebook calls this ability <strong>AIR-ATTACK<\/strong>; cards print <strong>AIR STRIKE<\/strong>. They are the same ability.<\/li><\/ul>","src":"CR 305.5.a, 305.2.a. Head Judge of Marvel Hero Rush Indonesia, 2–3 Sep 2026."},{"id":"F-22","q":"A Character left the field and came back this turn. Can it attack again?","a":"<p>Yes, if it is back in your BATTLE and the attack order (FRONT → WINGs → BACK) has not passed its area yet. A card that leaves the FIELD becomes a <strong>new card<\/strong>, so its attack opportunity and its ONCE PER TURN effects are fresh again.<\/p>","src":"CR 301.45.b, 303.2.a.4.4. Head Judge of Marvel Hero Rush Indonesia, 12 Aug, 20 Sep and 22 Sep 2026."}]},{"t":"Counter Step and Counter Phase","items":[{"id":"F-23","q":"How does the Counter Step work? Can we counter more than once?","a":"<ul><li>In each battle's Counter Step, players <strong>alternate one action at a time<\/strong>, starting with the <strong>opponent<\/strong> of the turn player.<\/li><li>An action is: a COUNTER CALL, activating a COUNTER·ACTI effect, or passing.<\/li><li>You can act again on your next turn to act. The step ends only when <strong>both players pass in a row<\/strong>.<\/li><li>The Counter Phase (after the Battle Phase) works the same way.<\/li><\/ul><p><strong>Example of one battle<\/strong> (Player A is the turn player; <em>counter<\/em> = a COUNTER CALL or activating a COUNTER·ACTI effect, <em>no counter<\/em> = pass):<\/p><ol><li>Player A attacks.<\/li><li>Player B: no counter.<\/li><li>Player A: counter.<\/li><li>Player B: counter.<\/li><li>Player A: counter.<\/li><li>Player B: no counter.<\/li><li>Player A: no counter.<\/li><li>Both players passed in a row (6 and 7), so the Counter Step ends and the battle is resolved.<\/li><\/ol><p>Player B's pass in step 2 did not end the step, because Player A did not pass right after it. Remember that each player can make only one COUNTER CALL in the Battle Phase (<a href=\"#faq/en/F-24\">F-24<\/a>), so Player A's two counters here cannot both be COUNTER CALLs.<\/p>","src":"CR 303.2.a.4.3.2.1–303.2.a.4.3.2.4, 303.2.a.5.1–303.2.a.5.3. This replaced the older \"one action each\" rule; announced by the Head Judge of Marvel Hero Rush Indonesia on 24 Sep 2026."},{"id":"F-24","q":"How many COUNTER CALLs can I make per turn?","a":"<p>Each player can COUNTER CALL:<\/p><ul><li><strong>once in the Battle Phase<\/strong>, no matter how many battles (Counter Steps) there are, and<\/li><li><strong>once in the Counter Phase<\/strong>.<\/li><\/ul>","src":"CR 303.2.a.4.3.2.3.1.1, 303.2.a.5.2.1.1. Head Judge of Marvel Hero Rush Indonesia, 16 Aug 2026."},{"id":"F-25","q":"Is a COUNTER CALL a normal CALL? Does a Lv4+ COUNTER CALL still need a cost?","a":"<p>Yes. COUNTER CALL follows the normal CALL rule, so a Lv4+ Character still needs its retreat cost. Only cards with the <strong>COUNTER<\/strong> ability can be COUNTER CALLed.<\/p>","src":"CR 301.19.f, 305.1.a. Head Judge of Marvel Hero Rush Indonesia, 31 Aug 2026."},{"id":"F-26","q":"When can I use ACTI and COUNTER·ACTI effects?","a":"<ul><li><strong>ACTI:<\/strong> only in <strong>your own Action Phase<\/strong>.<\/li><li><strong>COUNTER·ACTI:<\/strong> in your own Action Phase, in <strong>either player's Counter Phase<\/strong>, and in the <strong>Counter Step<\/strong>.<\/li><\/ul>","src":"CR 201.10.f.2–201.10.f.3."}]},{"t":"Effects and timing","items":[{"id":"F-27","q":"Is there a chain or stack?","a":"<p>No. An effect <strong>resolves as soon as it triggers or is activated<\/strong>. If several effects trigger at the same time, they wait and resolve one at a time:<\/p><ul><li>if one player has several, that player chooses the order;<\/li><li>if both players have some, the <strong>turn player orders and resolves theirs first<\/strong>, then the opponent.<\/li><\/ul>","src":"CR 304.1.c, 304.1.e–g, 304.2.a. Head Judge of Marvel Hero Rush Indonesia, 13 Aug, 20 Sep and 22 Oct 2026."},{"id":"F-28","q":"What if a new effect triggers while another effect is resolving?","a":"<ul><li>Finish the current effect, then resolve the new (derived) trigger <strong>right away<\/strong>, before the effects that were already waiting.<\/li><li>If a player's new triggers form a group, nothing can be put in the middle of that group. If the same player still has an older trigger waiting, they choose whether it goes before or after the whole new group.<\/li><\/ul><p>Example: Player A's 「Antimatter」 Iron Man prunes Player B's Gwen, while B's Pym Arrow (triggered by the Antimatter CALL) is still waiting. B may resolve Pym first and then Gwen + Silk, or Gwen + Silk first and then Pym, but not Gwen → Pym → Silk.<\/p>","src":"CR 304.1.h, 304.1.f. Head Judge of Marvel Hero Rush Indonesia, 22 Oct 2026."},{"id":"F-29","q":"Must I use every effect? What if I can only do part of it?","a":"<ul><li>An effect that says <strong>\"may\"<\/strong> is optional. Without \"may\" it is <strong>mandatory<\/strong>.<\/li><li>Once an effect starts resolving, do <strong>as much of it as you can<\/strong>.<\/li><li>Text after <strong>\"after doing so\"<\/strong> happens only if everything before it was done in full.<\/li><li>\"Up to X\" lets you choose 0; choosing 0 counts as not resolving the effect.<\/li><\/ul>","src":"CR 304.1.a–b, 304.1.d, 301.38.a, 301.34.a–b. Head Judge of Marvel Hero Rush Indonesia, 20 Sep 2026."},{"id":"F-30","q":"Can I use an effect if its result has no valid target?","a":"<p>Yes, if the first part can be done. The first part (for example discarding or pruning the card) happens and the result does nothing. Examples:<\/p><ul><li>Discarding <a class=\"nw-chip rf-chip\" href=\"#c=SD01-006\" data-card=\"SD01-006\"><b>SD01-006<\/b><\/a> 「Hourglass Bite」 Black Widow from your HAND when the opponent has no matching Character.<\/li><li><a class=\"nw-chip rf-chip\" href=\"#c=SP01-006\" data-card=\"SP01-006\"><b>SP01-006<\/b><\/a> 「Spider-Archenemy」 Red Goblin: you prune Red Goblin and 1 other Character or Attached Card on your field, and X is the total Lv of the cards you pruned. You may do this even if your opponent has <strong>no Character with exactly LvX<\/strong> in BATTLE. Your two cards are pruned, and nothing happens to your opponent.<\/li><\/ul>","src":"Head Judge of Marvel Hero Rush Indonesia, 25 Oct 2026 (he noted he might be wrong; this will be updated if an official ruling says otherwise)."},{"id":"F-31","q":"I drew a card while effects were resolving. Can its HAND trigger still be used?","a":"<p>Yes. If your HAND changes while effects of one timing are resolving, and the new card has a trigger for that same timing, it counts as triggered at that timing.<\/p><p>Example:<\/p><ol><li>Your opponent has <a class=\"nw-chip rf-chip\" href=\"#c=SD03-011\" data-card=\"SD03-011\"><b>SD03-011<\/b><\/a> 「Ancestral Plane」 New Black Panther in a WING. Its AUTO gives your Character in FRONT Power -500.<\/li><li>You call <a class=\"nw-chip rf-chip\" href=\"#c=BP01-077\" data-card=\"BP01-077\"><b>BP01-077<\/b><\/a> 「I Need You」 Captain America into your FRONT. It enters the field, and at the same moment its Power decreases because of Ancestral Plane.<\/li><li>I Need You's trigger resolves: you draw 1 card and it is <a class=\"nw-chip rf-chip\" href=\"#c=BP01-063\" data-card=\"BP01-063\"><b>BP01-063<\/b><\/a> 「Time Abduction」 Loki (\"when the Power of your character decreases\"). Then you place the top card of your Deck face-down into your BASE.<\/li><li>The Power decrease happened at the same timing that is still being resolved, so Time Abduction counts as triggered. You may prune it from your HAND and use its effect.<\/li><\/ol>","src":"CR 304.1.k. Head Judge of Marvel Hero Rush Indonesia, 21 Oct 2026."},{"id":"F-32","q":"What happens in the End Phase, and in what order?","a":"<ol><li>Effects that trigger \"when the turn ends\" trigger and resolve.<\/li><li>Effects that last \"this turn\" end.<\/li><li>The turn player discards down to 9 cards in HAND.<\/li><\/ol>","src":"CR 303.2.a.6.1.1–303.2.a.6.1.3. Head Judge of Marvel Hero Rush Indonesia, 4 Oct 2026."}]},{"t":"Power, R and leaving the field","items":[{"id":"F-33","q":"Does a Character at Power 0 retreat immediately?","a":"<p>Yes. As soon as an effect reduces a Character's Power to 0, it is locked in to retreat.<\/p>","src":"CR 301.16.a.1, 301.16.b. Head Judge of Marvel Hero Rush Indonesia, 31 Oct 2026."},{"id":"F-34","q":"\"Becomes X\" vs \"+X / -X\": which one wins?","a":"<p>A <strong>change<\/strong> (\"R changes to 3\", \"Lv changes to 6\") replaces earlier increases and decreases. An increase or decrease that comes <strong>after<\/strong> the change is applied on top of the new value. If two changes apply, the later one wins; if the later one ends, the earlier one applies again. The detailed cases are in CR 301.41.<\/p><p>Examples:<\/p><ul><li><a class=\"nw-chip rf-chip\" href=\"#c=BP01-097\" data-card=\"BP01-097\"><b>BP01-097<\/b><\/a> 「Original Mutant」 Namor is in your BATTLE: the R of your Character in FRONT <strong>changes to 3<\/strong>. If that Character then gets R+1 (for example from <a class=\"nw-chip rf-chip\" href=\"#c=BP01-117\" data-card=\"BP01-117\"><b>BP01-117<\/b><\/a> 「Ancestral Blessing」 New Black Panther), its R is <strong>4<\/strong>: the +1 is added on top of the change.<\/li><li><a class=\"nw-chip rf-chip\" href=\"#c=SD04-001\" data-card=\"SD04-001\"><b>SD04-001<\/b><\/a> 「God of Trick」 Loki is attached to a Character: its R <strong>changes to 0<\/strong> and it gets Power+1000. Any R+X that Character had before is gone. The Power+1000 is an increase, so it is added normally.<\/li><li>That Character's controller has Namor in BATTLE and the Character is in FRONT. Two changes now apply: Loki's (R becomes 0) and Namor's (R becomes 3). The one that started applying <strong>later<\/strong> wins. If Loki was attached after Namor was already there, the R is 0; if Namor arrives later, the R is 3, and if Namor then leaves, Loki's change applies again (R 0).<\/li><\/ul>","src":"CR 301.41.a–k (especially 301.41.d and 301.41.f). Head Judge of Marvel Hero Rush Indonesia, 26 Aug and 24 Sep 2026."},{"id":"F-35","q":"What counts as \"Power decreased\" (for cards like 「Time Abduction」 Loki)?","a":"<p>Any effect that gives a Character <strong>Power -X<\/strong> counts, including an effect from your own card. A buff that ends is <strong>not<\/strong> a decrease.<\/p>","src":"Head Judge of Marvel Hero Rush Indonesia, 29 Aug, 24 Sep and 6 Oct 2026."},{"id":"F-36","q":"What is the difference between RETREAT, retreat, discard and prune?","a":"<ul><li><strong>RETREAT<\/strong> (capitals) is the area. <strong>retreat<\/strong> (lowercase) is the action.<\/li><li>Only cards <strong>on the FIELD<\/strong> are retreated. Moving a card from your HAND or Deck to the RETREAT is a <strong>discard<\/strong>.<\/li><li><strong>Prune<\/strong> puts a card into the <strong>VOID<\/strong>.<\/li><li>\"Number of cards you retreat\" counts only the cards you retreated (for example as a CALL cost), not the Attached Cards that follow them. \"Cards sent to RETREAT\" counts every card that enters the RETREAT.<\/li><\/ul>","src":"CR 301.15, 301.16, 301.17.a, 302.8.a. Head Judge of Marvel Hero Rush Indonesia, 26 Aug and 10 Oct 2026."}]},{"t":"Attached Cards and swaps","items":[{"id":"F-37","q":"What happens to Attached Cards?","a":"<ul><li>An Attached Card is <strong>not a Character<\/strong>: it cannot be retreated to pay a CALL cost and does not count as a Character in BATTLE.<\/li><li>It <strong>keeps its own effects<\/strong>.<\/li><li>It <strong>follows<\/strong> its Character to the RETREAT, the HAND or the Deck, and always goes back to its <strong>owner<\/strong>.<\/li><li>If its Character stops being a Character (for example it is turned face-down), the Attached Cards go to the RETREAT.<\/li><li>An Attached Card cannot attach again to the same Character, and the order of Attached Cards cannot be changed.<\/li><\/ul>","src":"CR 301.25.a–c, 301.25.d–l, 301.25.b, 301.25.n, 301.3. Head Judge of Marvel Hero Rush Indonesia, 17 Aug, 28 Aug, 5 and 16 Sep, 4 and 26 Oct 2026."},{"id":"F-38","q":"My opponent attached Riot to my Character and Riot's effect retreated it. Can I use 「Turn The Tide」?","a":"<p>No. Once attached, Riot is on <strong>your<\/strong> Character, so the retreat comes from an effect on your own side, not from \"your opponent's effect\".<\/p>","src":"Head Judge of Marvel Hero Rush Indonesia, 25 Oct 2026."},{"id":"F-43","q":"Can 「Turn The Tide」 Captain America return a Character that retreated because its Power became 0?","a":"<p>Yes. If an <strong>opponent's effect<\/strong> reduces your Lv4 or lower (Human) Character's Power to 0, the Character retreats by the game rule, and this counts as entering the RETREAT from BATTLE by your opponent's effect. You may use <a class=\"nw-chip rf-chip\" href=\"#c=BP01-066\" data-card=\"BP01-066\"><b>BP01-066<\/b><\/a> / <a class=\"nw-chip rf-chip\" href=\"#c=EB01-012\" data-card=\"EB01-012\"><b>EB01-012<\/b><\/a> 「Turn The Tide」 Captain America.<\/p>","src":"CR 301.16.a.1, 301.16.b. Confirmed by the Head Judge of Marvel Hero Rush Indonesia (Nov 2026)."},{"id":"F-39","q":"What exactly does a swap exchange?","a":"<p>The two cards exchange <strong>positions<\/strong>, their <strong>current states<\/strong> (for example \"has attacked\", buffs and debuffs given by effects) and their <strong>Attached Cards<\/strong>. A bonus that comes from a card's own AUTO effect stays with that card.<\/p>","src":"CR 301.18.a–c. Head Judge of Marvel Hero Rush Indonesia, 23 Oct 2026."},{"id":"F-40","q":"What does \"loses its effects\" remove (for example Anti-Venom)?","a":"<p>The card loses <strong>all<\/strong> its effect types, effect text and abilities, including abilities such as AIR STRIKE, and any effect it would gain later. <strong>UNIQUE is the exception<\/strong>: it cannot be lost. Effects from <strong>other<\/strong> cards that are applying to it (for example a -2000) still apply.<\/p>","src":"CR 301.33.a, 305.6.a. Head Judge of Marvel Hero Rush Indonesia, 29 Sep and 7 Oct 2026."}]},{"t":"Card text","items":[{"id":"F-41","q":"The Indonesian and English text of a card are different. Which one do I follow?","a":"<p>Follow the <strong>English<\/strong> text until an Indonesian erratum is published. The English text was translated directly from the original Chinese, while the Indonesian text went through English first. See <strong>Errata &amp; Text Differences<\/strong> for the known cases.<\/p>","src":"Head Judge of Marvel Hero Rush Indonesia, 16 Aug 2026."},{"id":"F-42","q":"Can I play English-language cards in Indonesian tournaments?","a":"<p>No, English-language <strong>cards<\/strong> are not legal in Indonesian tournaments. English <strong>Rush Points<\/strong> may be used.<\/p>","src":"Head Judge of Marvel Hero Rush Indonesia, 13 Aug 2026."},{"id":"F-44","q":"What is the difference between a \"character\" and a \"card\" in card text?","a":"<p>They are <strong>not<\/strong> the same, so read the card text carefully.<\/p><ul><li><strong>Card<\/strong> means any card: a Character, a Face-Down Card or an Attached Card.<\/li><li><strong>Character<\/strong> means only a face-up Character. Every card in your Deck is a Character, but on the FIELD it can stop being a Character:<ul><li>a <strong>Face-Down Card<\/strong> in BASE is a card, not a Character (it becomes a Character again when flipped face-up);<\/li><li>an <strong>Attached Card<\/strong> is a card, not a Character (it becomes a Character again when detached).<\/li><\/ul><\/li><li>So an effect that says \"<strong>1 of your characters<\/strong>\" cannot choose a Face-Down Card or an Attached Card, while an effect that says \"<strong>1 of your cards<\/strong>\" can.<\/li><\/ul><p>Examples:<\/p><ul><li><a class=\"nw-chip rf-chip\" href=\"#c=BP01-061\" data-card=\"BP01-061\"><b>BP01-061<\/b><\/a> 「Follow Shadow」 New Black Panther: \"retreat 2 of your <strong>cards<\/strong> in BASE\" → face-up Characters and Face-Down Cards both count.<\/li><li><a class=\"nw-chip rf-chip\" href=\"#c=SP01-026\" data-card=\"SP01-026\"><b>SP01-026<\/b><\/a> 「Vigil of Love」 Amazing Spider-Man: \"swap this card in HAND and 1 of your <strong>card<\/strong> with 【Ghost-Spider】 or 【Gwen】…\" → it can also swap with a Gwen that is an Attached Card.<\/li><li>A CALL cost retreats <strong>Characters<\/strong> (Face-Down Cards are allowed by a special rule and count as Lv1), so an Attached Card can never be part of a CALL cost.<\/li><\/ul>","src":"CR 201.1–201.2, 301.21.a–b, 301.21.g, 301.22.a, 301.25.a, 301.26.a, 301.19.b."}]}],"errIntro":"<p>Official corrections to card text, and known differences between the Indonesian and English printings.<\/p><ul><li><strong>Errata<\/strong> change how a card works. Play the card as the corrected text says, even if your copy is printed with the old text.<\/li><li><strong>Text differences<\/strong> are cases where the Indonesian and English text say different things, or a name or term is printed differently, without an official erratum yet. Until one is published, <strong>follow the English text<\/strong> (see <a href=\"#faq/F-41\">Rules FAQ F-41<\/a>).<\/li><\/ul><p>Cards with an erratum show an <strong>Errata<\/strong> badge on the Cards page. The text in the MHR Deck Lab database already uses the corrected wording.<\/p><p><strong>About version numbers:<\/strong> \"V.1\" is the name of the first official errata list. From V.2 on, version numbers are <strong>MHR Deck Lab labels<\/strong>, because official errata are not always announced with a version number. A new version starts each time a new set is released; errata announced in the same period share one version number.<\/p><p class=\"rf-note\">Last checked: 2 November 2026. This page is maintained by MHR Deck Lab and is not an official document.<\/p>","err":[{"t":"Part 1 — Official errata","intro":"","groups":[{"t":"Errata V.1 — Indonesian text (28 Aug 2026)","intro":"<p><em>Source: \"MHR ERRATA V.1\", the official errata list shared by the Marvel Hero Rush Indonesia team in the community group. These errata correct the <strong>Indonesian<\/strong> text only. The English text already said the same as the corrected text.<\/em><\/p><p>Each entry shows: what changed (in English), then the Indonesian text before → after.<\/p>","items":[{"id":"E-01","t":"<a class=\"nw-chip rf-chip\" href=\"#c=BP01-002\" data-card=\"BP01-002\"><b>BP01-002<\/b><\/a> 「Covert Ops」 Black Widow","cards":["BP01-002"],"a":"<p>Change: the -2000 can only target an opponent's Character <strong>in BATTLE<\/strong> (not in BASE).<\/p><ul><li>Before: \"…1 karakter lawan mendapatkan Power -2000 pada giliran ini.\"<\/li><li>After: \"…1 karakter lawan <strong>di BATTLE<\/strong> mendapatkan Power -2000 pada giliran ini.\"<\/li><\/ul>"},{"id":"E-02","t":"<a class=\"nw-chip rf-chip\" href=\"#c=BP01-026\" data-card=\"BP01-026\"><b>BP01-026<\/b><\/a> / <a class=\"nw-chip rf-chip\" href=\"#c=SD01-018\" data-card=\"SD01-018\"><b>SD01-018<\/b><\/a> 「Cosmic Legacy」 Silver Surfer","cards":["BP01-026","SD01-018"],"a":"<p>Change: it triggers only when it goes to RETREAT <strong>from the FIELD<\/strong> as a CALL cost.<\/p><ul><li>Before: \"Saat kartu ini masuk ke RETREAT sebagai syarat pemanggilan, …\"<\/li><li>After: \"Saat kartu ini masuk ke RETREAT <strong>dari FIELD<\/strong> sebagai syarat pemanggilan, …\"<\/li><li><a class=\"nw-chip rf-chip\" href=\"#c=SD01-018\" data-card=\"SD01-018\"><b>SD01-018<\/b><\/a> is a reprint of <a class=\"nw-chip rf-chip\" href=\"#c=BP01-026\" data-card=\"BP01-026\"><b>BP01-026<\/b><\/a> with the same text, so the same correction applies.<\/li><\/ul>"},{"id":"E-03","t":"<a class=\"nw-chip rf-chip\" href=\"#c=BP01-037\" data-card=\"BP01-037\"><b>BP01-037<\/b><\/a> 「Ultron Army」 Ultron","cards":["BP01-037"],"a":"<p>Change: the Character you place must have <strong>\"Ultron\" in its name<\/strong>, not in its trait.<\/p><ul><li>Before: \"…1 karakter Lv2 atau lebih rendah dengan <strong>trait<\/strong> [Ultron] dari RETREAT ke FIELD.\"<\/li><li>After: \"…1 karakter Lv2 atau lebih rendah dengan <strong>nama<\/strong> [Ultron] dari RETREAT ke FIELD.\"<\/li><\/ul>"},{"id":"E-04","t":"<a class=\"nw-chip rf-chip\" href=\"#c=BP01-043\" data-card=\"BP01-043\"><b>BP01-043<\/b><\/a> 「Reinstall」 Vision","cards":["BP01-043"],"a":"<p>Change: you retreat <strong>your own<\/strong> Ultron; the Character you place must be <strong>Lv3 or lower with the (Machine) trait, from your HAND<\/strong>.<\/p><ul><li>Before: \"Retreat 1 karakter dengan nama [Ultron]. Jika dilakukan, ambil 1 kartu dari atas deck lalu tempatkan 1 karakter Lv3 atau lebih rendah Anda.\"<\/li><li>After: \"Retreat 1 karakter <strong>sendiri<\/strong> dengan nama [Ultron]. Jika dilakukan, ambil 1 kartu dari atas deck lalu tempatkan 1 karakter Lv3 atau lebih rendah Anda <strong>dengan Trait (Machine) dari HAND ke FIELD Anda<\/strong>.\"<\/li><\/ul>"},{"id":"E-05","t":"<a class=\"nw-chip rf-chip\" href=\"#c=BP01-046\" data-card=\"BP01-046\"><b>BP01-046<\/b><\/a> 「Banner Assimilation」 Hulk","cards":["BP01-046"],"a":"<p>Change: only Avengers on <strong>your<\/strong> FIELD reduce its Lv.<\/p><ul><li>Before: \"…X jumlah karakter dengan trait [Avengers] di FIELD.\"<\/li><li>After: \"…X jumlah karakter dengan trait [Avengers] di FIELD <strong>Anda<\/strong>.\"<\/li><\/ul>"},{"id":"E-06","t":"<a class=\"nw-chip rf-chip\" href=\"#c=BP01-052\" data-card=\"BP01-052\"><b>BP01-052<\/b><\/a> 「Nemesis」 Hulk Buster","cards":["BP01-052"],"a":"<p>Change: it triggers only when <strong>your own<\/strong> Lv4+ (Machine) Character enters the FIELD.<\/p><ul><li>Before: \"Saat karakter Lv4+ dengan trait [Machine] masuk ke FIELD, …\"<\/li><li>After: \"Saat karakter Lv4+ dengan trait [Machine] <strong>Anda<\/strong> masuk ke FIELD, …\"<\/li><\/ul>"},{"id":"E-07","t":"<a class=\"nw-chip rf-chip\" href=\"#c=BP01-090\" data-card=\"BP01-090\"><b>BP01-090<\/b><\/a> 「Freedom Decision」 Captain America","cards":["BP01-090"],"a":"<p>Change: the Power -X can only target an opponent's Character <strong>in BATTLE<\/strong>.<\/p><ul><li>Before: \"…1 karakter lawan mendapat Power -X pada giliran ini.\"<\/li><li>After: \"…1 karakter lawan <strong>di BATTLE<\/strong> mendapat Power -X pada giliran ini.\"<\/li><\/ul>"},{"id":"E-08","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SD01-007\" data-card=\"SD01-007\"><b>SD01-007<\/b><\/a> 「Ordnance Drop」 Iron Man","cards":["SD01-007"],"a":"<p>Change: the -2000 can only target an opponent's Lv5 or lower Character <strong>in BATTLE<\/strong> (not anywhere on the FIELD).<\/p><ul><li>Before: \"…1 karakter musuh Lv5 atau lebih rendah di <strong>FIELD<\/strong> mendapatkan -2000 Power…\"<\/li><li>After: \"…1 karakter musuh Lv5 atau lebih rendah di <strong>BATTLE<\/strong> mendapatkan -2000 Power…\"<\/li><\/ul>"},{"id":"E-09","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SD04-002\" data-card=\"SD04-002\"><b>SD04-002<\/b><\/a> 「Clustered Arrow」 Hawkeye","cards":["SD04-002"],"a":"<p>Change: it triggers whenever it is <strong>placed<\/strong> onto the FIELD, not only when called.<\/p><ul><li>Before: \"Saat kartu ini <strong>dipanggil<\/strong> ke FIELD, …\"<\/li><li>After: \"Saat kartu ini <strong>ditempatkan<\/strong> ke FIELD, …\"<\/li><\/ul>"},{"id":"E-10","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SD04-003\" data-card=\"SD04-003\"><b>SD04-003<\/b><\/a> 「Quantum Rewind」 Ant-Man","cards":["SD04-003"],"a":"<p>Change: it triggers only when it goes to RETREAT <strong>from the FIELD<\/strong>.<\/p><ul><li>Before: \"Saat kartu ini ditempatkan ke RETREAT, …\"<\/li><li>After: \"Saat kartu ini ditempatkan ke RETREAT <strong>dari FIELD<\/strong>, …\"<\/li><\/ul>"},{"id":"E-11","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SD04-005\" data-card=\"SD04-005\"><b>SD04-005<\/b><\/a> 「Quantum Teleportation」 Ant-Man","cards":["SD04-005"],"a":"<p>Change: it triggers only when it goes to RETREAT <strong>from the FIELD<\/strong>.<\/p><ul><li>Before: \"Saat kartu ini ditempatkan ke RETREAT, …\"<\/li><li>After: \"Saat kartu ini ditempatkan ke RETREAT <strong>dari FIELD<\/strong>, …\"<\/li><\/ul>"}]},{"t":"Errata V.2 (October 2026)","intro":"<p><em>Source: official errata announced in October 2026. Unlike V.1, these also change English text.<\/em><\/p>","items":[{"id":"E-12","t":"<a class=\"nw-chip rf-chip\" href=\"#c=BP01-061\" data-card=\"BP01-061\"><b>BP01-061<\/b><\/a> 「Follow Shadow」 New Black Panther — English and Indonesian","cards":["BP01-061"],"a":"<p>Change: the cost is retreating <strong>any 2 of your cards in BASE<\/strong>, not only set (face-down) cards.<\/p><ul><li>EN before: \"You retreat 2 of your <strong>set<\/strong> cards in BASE. …\" → after: \"You retreat 2 of your cards in BASE. …\"<\/li><li>ID before: \"RETREAT 2 kartu <strong>tertutup<\/strong> milik Anda di BASE. …\" → after: \"RETREAT 2 kartu milik Anda di BASE. …\"<\/li><li>Announced 13 Oct 2026.<\/li><\/ul>"},{"id":"E-13","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SP01-026\" data-card=\"SP01-026\"><b>SP01-026<\/b><\/a> 「Vigil of Love」 Amazing Spider-Man — English","cards":["SP01-026"],"a":"<p>Change: the COUNTER·ACTI swaps with <strong>any of your cards<\/strong> named Ghost-Spider or Gwen on the field, including an Attached Card, not only a Character.<\/p><ul><li>EN before: \"…swap this card in HAND and 1 of your <strong>characters<\/strong> with 【Ghost-Spider】 or 【Gwen】 in their names on the field.\" → after: \"…1 of your <strong>card<\/strong> with 【Ghost-Spider】 or 【Gwen】…\"<\/li><li>The Indonesian text already said \"1 kartu Anda di FIELD\".<\/li><\/ul>"},{"id":"E-14","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SP01-061\" data-card=\"SP01-061\"><b>SP01-061<\/b><\/a> 「Spider-Archenemy」 Mr. Negative — Indonesian","cards":["SP01-061"],"a":"<p>Change: compare your set cards in BASE with your Characters <strong>in BASE<\/strong>, not in BATTLE.<\/p><ul><li>ID before: \"…jumlah kartu tertutup di BASE sama dengan jumlah karakter di <strong>BATTLE<\/strong> Anda…\" → after: \"…jumlah karakter di <strong>BASE<\/strong> Anda…\"<\/li><li>The English text already said \"your characters in BASE\".<\/li><\/ul>"}]}]},{"t":"Part 2 — Text differences (no official erratum yet)","intro":"","groups":[{"t":"","intro":"<p>Until an erratum is published, follow the English text.<\/p>","items":[{"id":"TD-01","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SD01-003\" data-card=\"SD01-003\"><b>SD01-003<\/b><\/a> 「Fire Support」 War Machine","cards":["SD01-003"],"a":"<ul><li>EN: \"When the R or the Power of <strong>your character<\/strong> increase…\" → triggers for <strong>any<\/strong> of your Characters.<\/li><li>ID: \"Saat R atau Power <strong>karakter ini<\/strong> meningkat…\" → reads as \"this Character\" only.<\/li><li>Follow the English: it triggers when any of your Characters gains R or Power. <em>Head Judge of Marvel Hero Rush Indonesia, 15 Aug 2026.<\/em><\/li><\/ul>"},{"id":"TD-02","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SD03-003\" data-card=\"SD03-003\"><b>SD03-003<\/b><\/a> 「Urgent Call」 Nick Fury","cards":["SD03-003"],"a":"<ul><li>The official English card list was updated: \"…If you do, you retreat this card.\" The old wording \"when the turn ends\" was removed, so Nick Fury is retreated <strong>right away<\/strong>, not at the end of the turn.<\/li><li>ID still says: \"Jika dilakukan, RETREAT kartu ini <strong>pada akhir giliran<\/strong>.\"<\/li><li>Follow the English. An Indonesian erratum has not been published yet.<\/li><\/ul>"},{"id":"TD-03","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SP01-080\" data-card=\"SP01-080\"><b>SP01-080<\/b><\/a> 「Spider-Archenemy」 Shocker","cards":["SP01-080"],"a":"<ul><li>EN (both effects): \"When this card enters the field <strong>by calling<\/strong>…\"<\/li><li>ID (both effects): \"Saat kartu ini <strong>ditempatkan<\/strong> ke FIELD…\" (= \"placed\", which also covers effects).<\/li><li>Follow the English: the effects trigger only when Shocker is <strong>called<\/strong>.<\/li><\/ul>"},{"id":"TD-05","t":"<a class=\"nw-chip rf-chip\" href=\"#c=BP01-083\" data-card=\"BP01-083\"><b>BP01-083<\/b><\/a> 「Freedom Watch」 / <a class=\"nw-chip rf-chip\" href=\"#c=SD03-014\" data-card=\"SD03-014\"><b>SD03-014<\/b><\/a> 「Freedom Watcher」 New Captain America","cards":["BP01-083","SD03-014"],"a":"<ul><li>The same card was printed with two names (BP01 \"Freedom Watch\", SD03 \"Freedom Watcher\"). This is a printing error, not an erratum.<\/li><li>They count as <strong>the same card<\/strong>: at most 3 in total in a deck, not 3 of each. <em>Head Judge of Marvel Hero Rush Indonesia, 28 Aug 2026.<\/em><\/li><\/ul>"},{"id":"TD-06","t":"AIR STRIKE vs AIR-ATTACK","cards":[],"a":"<ul><li>Cards print the ability as <strong>AIR STRIKE<\/strong>; the Comprehensive Rules call it <strong>AIR-ATTACK<\/strong> (CR 305.5). They are the same ability.<\/li><\/ul>"},{"id":"TD-07","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SP01-005\" data-card=\"SP01-005\"><b>SP01-005<\/b><\/a> 「Endgame Battle」 Iron Man","cards":["SP01-005"],"a":"<ul><li>EN: \"…you retreat all your cards with 【<strong>Buster<\/strong>】 in their names on the field…\"; the AUTO also counts 【Buster】 cards in RETREAT.<\/li><li>The official <strong>Indonesian card list<\/strong> writes 【<strong>Armor<\/strong>】 instead of 【Buster】.<\/li><li>Follow the English: the effect refers to cards with <strong>\"Buster\"<\/strong> in their names (Hulk Buster cards).<\/li><\/ul>"},{"id":"TD-08","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SP01-043\" data-card=\"SP01-043\"><b>SP01-043<\/b><\/a> 「Spider-Archenemy」 Kingpin","cards":["SP01-043"],"a":"<ul><li>EN: \"…place 1 of your characters with 【<strong>Archenemy<\/strong>】 in their features from HAND onto your BATTLE.\"<\/li><li>ID: \"…menempatkan 1 karakter dari tangan dengan <strong>nama<\/strong> 【<strong>Nemesis<\/strong>】 ke BATTLE Anda.\"<\/li><li>The two texts use a different word (<strong>Archenemy<\/strong> / <strong>Nemesis<\/strong>). Follow the English text.<\/li><\/ul>"},{"id":"TD-09","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SP01-018\" data-card=\"SP01-018\"><b>SP01-018<\/b><\/a> 「Spider-Archenemy」 Kraven the Hunter","cards":["SP01-018"],"a":"<ul><li>EN: \"…gets Power+X000. X is the number of <strong>abilities<\/strong> your opponent's characters on BATTLE have.\"<\/li><li>ID: \"…X adalah jumlah total <strong>karakter dengan efek<\/strong> di BATTLE lawan.\"<\/li><li>Follow the English: count the <strong>abilities<\/strong> (UNIQUE, BLOCK, AIR STRIKE, COUNTER, etc.) on your opponent's Characters in BATTLE, not the number of Characters that have effects.<\/li><\/ul>"},{"id":"TD-10","t":"<a class=\"nw-chip rf-chip\" href=\"#c=SP01-038\" data-card=\"SP01-038\"><b>SP01-038<\/b><\/a> 「Spider-Archenemy」 Boomerang","cards":["SP01-038"],"a":"<ul><li>EN: \"ACTI【BATTLE / <strong>ONCE PER TURN<\/strong>】 … you draw 1 card extra.\"<\/li><li>ID: \"ACTI (BATTLE / <strong>TWICE PER TURN<\/strong>) … Anda <strong>dapat<\/strong> menarik 1 kartu.\"<\/li><li>Follow the English: the effect can be used <strong>once per turn<\/strong>, and the extra draw is not optional.<\/li><\/ul>"}]}]}]};
/* v7.26 — Rules FAQ versi Bahasa Indonesia (nomor & urutan sama dengan RF_DATA.faq). */
const RF_FAQ_ID = {"intro":"<p>Jawaban untuk pertanyaan yang paling sering ditanyakan pemain baru, berdasarkan <strong>Comprehensive Rules 1.03<\/strong> (12 Agu 2026) dan pernyataan <strong>Head Judge of Marvel Hero Rush Indonesia<\/strong>. Setiap jawaban mencantumkan sumber dan tanggalnya.<\/p><p class=\"rf-note\">Ini FAQ komunitas buatan MHR Deck Lab, bukan dokumen resmi. Jika ada ruling resmi yang berbeda, ruling resmi yang berlaku. Aturan bisa berubah: selalu cek versi aturan dan tanggalnya. Versi Bahasa Indonesia ini adalah terjemahan dari versi bahasa Inggris; jika ada perbedaan arti, versi bahasa Inggris yang menjadi acuan.<\/p>","gloss":"<ul><li><strong>Memanggil (CALL)<\/strong> — memasukkan karakter dari tangan ke FIELD lewat aksi CALL. Karakter Lv3 atau lebih rendah dipanggil tanpa biaya. Karakter Lv4 atau lebih tinggi butuh biaya: retreat karakter di FIELD Anda yang total Lv-nya sama dengan Lv karakter yang dipanggil (setiap kartu tertutup dihitung Lv1). Di teks kartu: \"dipanggil\" atau \"melakukan pemanggilan\".<\/li><li><strong>Menempatkan (place)<\/strong> — memasukkan kartu dalam keadaan terbuka ke suatu area karena efek atau aturan, misalnya \"tempatkan kartu ini dari tangan ke WING\". Menempatkan karena efek <strong>bukan<\/strong> CALL: tidak ada biaya CALL dan tidak dihitung sebagai pemanggilan.<\/li><li><strong>Kartu tertutup (Face-Down Card)<\/strong> — kartu yang diletakkan tertelungkup di BASE, misalnya lewat Base Deployment (1 kartu dari tangan ke BASE dalam keadaan tertutup, lalu tarik 1 kartu). Di teks kartu Inggris disebut \"set card\". Kartu tertutup bukan karakter dan tidak punya efek; hanya pemiliknya yang boleh melihatnya. Kartu ini tetap dihitung dalam batas 6 kartu BASE dan boleh di-retreat sebagai biaya CALL (dihitung Lv1).<\/li><li><strong>Membalik (flip)<\/strong> — membuat kartu tertutup menjadi terbuka sehingga kembali menjadi karakter. Hanya boleh dilakukan jika ada efek yang menyuruhnya (lihat F-11).<\/li><li><strong>Kartu terpasang (Attached Card)<\/strong> — kartu yang dipasang (attach) di bawah sebuah karakter karena efek. Kartu ini bukan karakter lagi, tetapi tetap sebuah kartu di FIELD dan tetap punya efeknya sendiri (termasuk UNIQUE). Kartu ini ikut berpindah bersama karakter yang dipasanginya (lihat F-37).<\/li><li><strong>Tukar (swap)<\/strong> — menukar posisi 2 kartu, misalnya kartu di tangan dengan kartu di FIELD, atau 2 kartu di FIELD. Kedua kartu juga bertukar keadaan (misalnya \"sudah menyerang\", Power +/- dari efek) dan kartu terpasangnya (lihat F-39).<\/li><li><strong>Weakness<\/strong> — area di BATTLE Anda yang <strong>kosong<\/strong> (tidak ada karakter di situ). Jika karakter lawan berhasil menyerang Weakness Anda, lawan menaruh 1 Rush Point dari Rush Point Deck-nya ke Timeline-nya. Pemain yang punya 9 Rush Point di Timeline menang.<\/li><li><strong>Retreat<\/strong> — memindahkan kartu dari FIELD ke area RETREAT, misalnya karakter yang kalah bertarung, karakter yang Power-nya menjadi 0, kartu yang dipakai sebagai biaya CALL, atau karena efek. \"RETREAT\" dengan huruf kapital adalah nama areanya.<\/li><li><strong>Buang (discard)<\/strong> — memindahkan kartu dari tangan atau dari Deck ke RETREAT. Kartu dari tangan atau Deck tidak disebut \"di-retreat\" (lihat F-36).<\/li><li><strong>Prune<\/strong> — memindahkan kartu ke VOID. VOID adalah area yang berbeda dari RETREAT; kartu di VOID terbuka dan boleh dilihat kedua pemain kapan saja.<\/li><li><strong>Tarik (draw)<\/strong> — mengambil kartu teratas Deck Anda ke tangan.<\/li><li><strong>Area permainan<\/strong> — <strong>tangan (HAND)<\/strong>; <strong>Deck<\/strong>; <strong>FIELD<\/strong> = BATTLE + BASE; <strong>BATTLE<\/strong> = 4 area tempat karakter bertarung: FRONT, 2 WING, dan BACK; <strong>BASE<\/strong> = area cadangan di FIELD, maksimal 6 kartu (karakter dan kartu tertutup); <strong>RETREAT<\/strong>; <strong>VOID<\/strong>; <strong>Timeline<\/strong> = tempat Rush Point yang sudah Anda dapat.<\/li><li><strong>Terpicu (trigger)<\/strong> — efek TRIG berjalan dengan sendirinya saat kondisinya terjadi, misalnya \"saat kartu ini masuk ke FIELD\".<\/li><li><strong>Diselesaikan (resolve)<\/strong> — efek dijalankan sampai selesai.<\/li><li><strong>Pemain yang sedang mendapat giliran (turn player)<\/strong> — pemain yang sedang menjalankan gilirannya. Pemain yang satunya disebut lawan.<\/li><li>Nama fase dan step (Action Phase, Battle Phase, Counter Step, Counter Phase, End Phase) serta kemampuan (ACTI, COUNTER·ACTI, AUTO, TRIG, UNIQUE, BLOCK, AIR STRIKE, COUNTER) ditulis dalam bahasa Inggris, sama seperti di kartu.<\/li><\/ul>","sections":[{"t":"Mulai bermain","items":[{"id":"F-01","q":"Apa saja aturan menyusun deck?","a":"<ul><li>Deck Anda berisi tepat <strong>50 karakter<\/strong>.<\/li><li>Paling banyak <strong>2 warna<\/strong>.<\/li><li>Paling banyak <strong>3 kartu dengan nama karakter yang sama<\/strong>.<\/li><li>Anda juga butuh <strong>Rush Point Deck berisi 9 Rush Point<\/strong>. Rush Point apa saja boleh dipakai.<\/li><\/ul>","src":"CR 101.1.b–d, 101.2.b–c."},{"id":"F-02","q":"Bagaimana cara menang?","a":"<p>Anda langsung menang begitu salah satu hal ini terjadi:<\/p><ul><li>ada <strong>9 Rush Point di Timeline Anda<\/strong>, atau<\/li><li><strong>Deck lawan berisi 0 kartu<\/strong>.<\/li><\/ul><p>Efek kartu juga bisa menyatakan seorang pemain sebagai pemenang.<\/p>","src":"CR 103.1.a–c."},{"id":"F-03","q":"Bagaimana permainan dimulai? Bolehkah saya mengganti kartu awal (mulligan)?","a":"<ul><li>Setiap pemain menarik <strong>6 kartu<\/strong>.<\/li><li>Setiap pemain boleh melakukan <strong>mulligan satu kali<\/strong>. Pemain pertama memutuskan lebih dulu, lalu pemain kedua.<\/li><li>Tentukan <strong>berapa banyak<\/strong> dari 6 kartu Anda yang ingin diganti: mulai 1 sampai semua 6 kartu. Anda juga boleh tetap memakai kartu di tangan apa adanya.<\/li><li>Taruh kartu yang diganti <strong>di bawah Deck<\/strong> dalam keadaan tertutup, lalu <strong>tarik kartu sebanyak jumlah yang sama<\/strong> dari atas Deck sehingga Anda kembali memegang 6 kartu. Setelah itu <strong>kocok Deck Anda<\/strong>.<\/li><li>Contoh: Anda mengganti 2 kartu. Taruh 2 kartu itu di bawah Deck, tarik 2 kartu dari atas, lalu kocok Deck.<\/li><\/ul><p>Coba langsung dengan <strong>Opening Draw Simulation<\/strong> di Deck Builder.<\/p>","src":"CR 303.1.d–e."},{"id":"F-04","q":"Apa yang berbeda pada giliran pertama pemain pertama?","a":"<ul><li>Pemain pertama hanya boleh melakukan CALL <strong>satu kali<\/strong> (bukan sampai 3 kali).<\/li><li>Pemain pertama boleh melakukan <strong>Base Deployment satu kali<\/strong>, sama seperti di giliran lain: tempatkan 1 kartu dari tangan secara tertutup ke BASE, lalu tarik 1 kartu.<\/li><li>Pemain pertama <strong>melewati Battle Phase<\/strong>.<\/li><\/ul>","src":"CR 303.2.a.3.1.2.3, 303.2.a.3.1.1, 303.2.a.4.1."},{"id":"F-05","q":"Apa saja yang bisa saya lakukan di Action Phase, dan berapa kali?","a":"<p>Urutannya bebas:<\/p><ul><li><strong>Base Deployment<\/strong> — tempatkan 1 kartu dari tangan Anda secara tertutup ke BASE Anda, lalu tarik 1 kartu. <strong>Sekali per giliran.<\/strong><\/li><li><strong>Action CALL<\/strong> — memanggil 1 karakter. <strong>Paling banyak 3 kali per giliran.<\/strong><\/li><li><strong>BATTLE-BASE MOVE<\/strong> — setiap karakter boleh berpindah antara BATTLE dan BASE <strong>sekali per giliran<\/strong>. Karakter yang ditempatkan ke FIELD pada giliran ini tidak boleh melakukannya.<\/li><li><strong>Mengaktifkan<\/strong> efek ACTI atau COUNTER·ACTI.<\/li><\/ul>","src":"CR 303.2.a.3.1.1–303.2.a.3.1.4."},{"id":"F-06","q":"Apakah ada batas jumlah kartu di tangan?","a":"<p>Ada. Di End Phase Anda, jika kartu di tangan Anda lebih dari <strong>9 kartu<\/strong>, buang kartu sampai tersisa 9.<\/p>","src":"CR 303.2.a.6.1.3."}]},{"t":"CALL, BASE, dan kartu tertutup","items":[{"id":"F-07","q":"Bagaimana cara memanggil karakter Lv4 atau lebih tinggi? Bolehkah biayanya diambil dari tangan?","a":"<ul><li>Untuk memanggil karakter Lv4+, <strong>retreat karakter di FIELD Anda<\/strong> yang <strong>total Lv-nya sama dengan<\/strong> Lv karakter yang dipanggil, lalu tempatkan karakter itu dari tangan.<\/li><li>Biayanya harus dari <strong>FIELD<\/strong> Anda (BATTLE atau BASE), bukan dari tangan.<\/li><li><strong>Kartu tertutup<\/strong> di BASE Anda boleh menjadi bagian dari biaya. Setiap kartu tertutup dihitung <strong>Lv1<\/strong>.<\/li><li>Karakter Lv3 atau lebih rendah tidak butuh biaya.<\/li><\/ul>","src":"CR 301.19.a–b, 301.21.g."},{"id":"F-08","q":"Apakah batas 6 kartu di BASE termasuk kartu tertutup?","a":"<p>Ya. BASE menampung <strong>total 6 kartu<\/strong>, karakter dan kartu tertutup digabung.<\/p>","src":"CR 302.6.a. Head Judge of Marvel Hero Rush Indonesia, 24 Sep 2026."},{"id":"F-09","q":"Apakah \"ditempatkan\" sama dengan \"dipanggil\"? Apakah efek \"saat dipanggil\" terpicu jika kartu ditempatkan oleh efek?","a":"<p>Tidak. <strong>CALL (memanggil)<\/strong> adalah aksi aturan di CR 301.19: menempatkan karakter dari tangan Anda dengan membayar biayanya. Efek yang berbunyi \"tempatkan\" atau \"letakkan\" memasukkan kartu ke FIELD tanpa CALL. Jadi efek yang berbunyi <strong>\"Saat kartu ini dipanggil ke FIELD\"<\/strong> (teks Inggris: \"when this card enters the field by calling\") tidak terpicu jika kartu itu ditempatkan oleh efek (misalnya oleh 「Turn The Tide」 Captain America).<\/p>","src":"CR 301.12.a, 301.19. Head Judge of Marvel Hero Rush Indonesia, 14 dan 29 Agu 2026."},{"id":"F-10","q":"Bolehkah karakter menyerang pada giliran saat ia dipanggil?","a":"<p>Boleh. Setiap karakter di BATTLE Anda mendapat satu kesempatan menyerang setiap giliran, dan tidak ada aturan yang melarang karakter yang baru masuk pada giliran ini untuk menyerang. Satu-satunya batasan untuk karakter baru adalah tidak boleh melakukan BATTLE-BASE MOVE pada giliran ini. Ini juga berlaku untuk karakter yang Anda masukkan lewat COUNTER CALL ke WING yang kosong saat FRONT Anda masih menyerang: karakter itu boleh menyerang saat urutan serangan sampai ke WING.<\/p>","src":"CR 303.2.a.4.4, 303.2.a.3.1.3.3. Head Judge of Marvel Hero Rush Indonesia, 15 Agu 2026."},{"id":"F-11","q":"Jika saya membalik kartu tertutup menjadi terbuka, apakah kartu itu dianggap \"masuk ke FIELD\"?","a":"<p>Tidak. Membalik kartu tertutup menjadi terbuka <strong>bukan<\/strong> menempatkannya ke FIELD, jadi efek \"saat kartu ini masuk ke FIELD\" (teks Inggris: \"when this card enters the field\") tidak terpicu. Karakter yang dibalik itu tetap boleh melakukan BATTLE-BASE MOVE pada giliran tersebut.<\/p><p><strong>Anda tidak boleh membalik kartu tertutup hanya karena ingin.<\/strong> Tidak ada aksi permainan untuk itu. Kartu tertutup hanya menjadi terbuka jika ada efek yang menyuruh membaliknya. Membalik kartu tertutup Anda sendiri tanpa efek seperti itu <strong>tidak legal<\/strong>.<\/p><p><strong>Contoh:<\/strong> <a class=\"nw-chip rf-chip\" href=\"#c=SP01-061\" data-card=\"SP01-061\"><b>SP01-061<\/b><\/a> 「Spider-Archenemy」 Mr. Negative. Efek ACTI【HAND】-nya bisa dipakai pada giliran Anda jika Anda belum melakukan pemanggilan dan jumlah kartu tertutup di BASE sama dengan jumlah karakter di BASE Anda. Mr. Negative ditempatkan dari tangan ke WING, lalu <em>semua kartu di BASE Anda dibalik<\/em> (teks Inggris: \"you flip all your cards in BASE\"). Kartu tertutup Anda menjadi terbuka <strong>karena efek ini<\/strong>:<\/p><ul><li>kartu-kartu itu tidak masuk ke FIELD, jadi efek \"saat kartu ini masuk ke FIELD\" miliknya tidak terpicu;<\/li><li>kartu-kartu itu tetap boleh melakukan BATTLE-BASE MOVE pada giliran ini;<\/li><li>Mr. Negative sendiri ditempatkan ke FIELD, jadi TRIG miliknya (\"saat kartu ini ditempatkan ke FIELD\") tetap terpicu.<\/li><\/ul><p>Tanpa efek seperti ini, kartu tertutup Anda tetap tertutup.<\/p>","src":"CR 301.22.a–c. Head Judge of Marvel Hero Rush Indonesia, 1 Okt 2026."},{"id":"F-12","q":"Apakah efek kartu tertutup terpicu saat kartu itu di-retreat?","a":"<p>Tidak. Kartu tertutup tidak punya efek, dan tetap dianggap kartu tertutup selama berpindah ke RETREAT. Contoh: 「Cosmic Legacy」 Silver Surfer dalam keadaan tertutup yang di-retreat sebagai biaya CALL tidak terpicu.<\/p>","src":"CR 301.21.c, 301.21.h."},{"id":"F-13","q":"Bagaimana cara kerja UNIQUE?","a":"<ul><li>Jika salah satunya UNIQUE, Anda tidak pernah boleh punya dua kartu dengan nama yang sama di FIELD Anda. Jika satu sudah ada, salinan lain tidak bisa masuk dengan cara apa pun.<\/li><li>Salinan dalam keadaan tertutup yang akan dibalik tetap tertutup dan hanya <strong>ditunjukkan (reveal)<\/strong>.<\/li><li>Anda <strong>boleh<\/strong> me-retreat salinan yang ada di FIELD Anda sebagai biaya CALL salinan lain, karena biaya dibayar sebelum kartu baru ditempatkan.<\/li><li>UNIQUE tidak bisa hilang, bahkan oleh efek seperti Anti-Venom.<\/li><li>UNIQUE adalah efek <strong>AUTO<\/strong>, jadi karakter UNIQUE dihitung sebagai kartu yang punya 【AUTO】 di efeknya. Contoh: <a class=\"nw-chip rf-chip\" href=\"#c=BP01-022\" data-card=\"BP01-022\"><b>BP01-022<\/b><\/a> 「Top Agent」 Black Widow boleh me-retreat karakter UNIQUE milik lawan yang Lv3 atau lebih rendah.<\/li><li><strong>Kartu terpasang juga dihitung.<\/strong> Kartu terpasang tetap sebuah kartu di FIELD Anda dan tetap punya efeknya sendiri, termasuk UNIQUE. Jadi kartu UNIQUE dan kartu lain dengan nama yang sama tidak pernah boleh ada bersamaan di FIELD Anda, baik sebagai karakter maupun sebagai kartu terpasang. Kartu yang akan melanggar aturan ini tidak bisa dipasang, dipanggil, atau ditempatkan. Contoh:<ul><li><a class=\"nw-chip rf-chip\" href=\"#c=SP01-021\" data-card=\"SP01-021\"><b>SP01-021<\/b><\/a> 「The Web of Destiny」 Spider-Man ada di FIELD Anda. Efeknya membolehkan Anda memasang (attach) karakter 【Web】 dari tangan, tetapi Anda tidak boleh memilih <a class=\"nw-chip rf-chip\" href=\"#c=SP01-033\" data-card=\"SP01-033\"><b>SP01-033<\/b><\/a> 「Spider-Mentor」 Spider-Man: namanya sama, jadi kartu itu tidak bisa dipasang.<\/li><li>「Spider-Mentor」 Spider-Man terpasang di salah satu karakter Anda. Selama kartu itu masih terpasang, Anda tidak bisa memanggil atau menempatkan 「The Web of Destiny」 Spider-Man (atau kartu lain bernama Spider-Man) ke FIELD Anda.<\/li><\/ul><\/li><\/ul>","src":"CR 305.6.a, 301.22.d, 301.25.k. Head Judge of Marvel Hero Rush Indonesia, 29 Sep, 7, 14 dan 17 Okt 2026."}]},{"t":"Menyerang","items":[{"id":"F-14","q":"Dalam urutan apa karakter saya menyerang?","a":"<ul><li>Di awal Battle Phase, Anda boleh <strong>menyusun ulang<\/strong> posisi sampai 4 karakter di BATTLE Anda, satu kali. Ini tidak dihitung sebagai perpindahan (move).<\/li><li>Lalu Anda menyerang dengan urutan <strong>FRONT → WING → BACK<\/strong>. Jika kedua WING berisi karakter, Anda yang memilih WING mana yang menyerang lebih dulu.<\/li><li>Setiap karakter punya <strong>satu<\/strong> kesempatan menyerang per giliran. Jika Anda memilih tidak menyerang dengan karakter itu, kesempatannya hilang.<\/li><\/ul>","src":"CR 303.2.a.4.2.1–303.2.a.4.2.2, 303.2.a.4.4, 303.2.a.4.7, 303.2.a.4.9.1."},{"id":"F-15","q":"Apa yang bisa saya serang? Apa itu Weakness?","a":"<ul><li>Karakter yang menyerang memilih <strong>1 karakter di BATTLE lawan<\/strong> atau <strong>1 Weakness<\/strong> yang berada dalam jangkauan <strong>R<\/strong>-nya.<\/li><li><strong>Weakness<\/strong> adalah area BATTLE yang kosong.<\/li><li>Jarak: BACK Anda → WING Anda = 1, WING Anda → FRONT Anda = 1, FRONT Anda → FRONT lawan = 1, FRONT lawan → WING lawan = 1, WING lawan → BACK lawan = 1.<\/li><li>Karakter dengan R 0, atau yang tidak punya target sah dalam jangkauannya, tidak bisa menyerang.<\/li><\/ul>","src":"CR 303.2.a.4.3.1.1, 301.20.a, 303.2.a.4.6."},{"id":"F-16","q":"Bagaimana hasil pertarungan ditentukan?","a":"<ul><li><strong>Karakter vs karakter:<\/strong> bandingkan Power. Power yang lebih tinggi menang dan yang kalah di-retreat. <strong>Power sama: keduanya kalah<\/strong> dan keduanya di-retreat. Power dibandingkan, bukan dikurangkan.<\/li><li><strong>Karakter vs Weakness:<\/strong> serangan berhasil, dan pemain yang menyerang menempatkan kartu teratas Rush Point Deck-nya ke Timeline-nya.<\/li><\/ul>","src":"CR 303.2.a.4.3.3.1–303.2.a.4.3.3.2."},{"id":"F-17","q":"Target saya menjadi tidak sah (targetnya keluar, atau area kosong yang diserang diisi lewat COUNTER CALL). Apa yang terjadi?","a":"<ul><li>Begitu Anda menyatakan serangan, pertarungan harus berlanjut: Anda tidak bisa membatalkannya.<\/li><li>Jika target menjadi tidak sah, selesaikan dulu semua efek, lalu <strong>pilih target baru yang sah<\/strong> dalam jangkauan R.<\/li><li>Jika tidak ada lagi target yang sah (misalnya R turun menjadi 0), pertarungan berakhir.<\/li><li>Jika karakter yang menyerang keluar dari FIELD, pertarungan berakhir.<\/li><li>COUNTER CALL yang tidak membuat target menjadi tidak sah tidak menyebabkan ganti target (retarget).<\/li><\/ul>","src":"CR 303.2.a.4.5, 303.2.a.4.3.1.3–303.2.a.4.3.1.6, 303.2.a.4.3.2.2, 303.2.a.4.3.2.5–303.2.a.4.3.2.6. Head Judge of Marvel Hero Rush Indonesia, 10 Agu, 18 Agu, 3 Sep dan 17 Okt 2026."},{"id":"F-18","q":"Apakah efek \"saat kartu ini menyerang\" terpicu lagi setelah ganti target?","a":"<p>Tidak. Efek itu terpicu saat serangan dinyatakan. Ganti target (retarget) hanya mengulang pemilihan target, jadi efek itu tidak terpicu lagi. Contoh: karakter yang memberi -2000 saat menyerang tidak memberi -2000 untuk kedua kalinya setelah ganti target.<\/p>","src":"CR 303.2.a.4.3.1.6. Head Judge of Marvel Hero Rush Indonesia, 15–16 Agu 2026."},{"id":"F-19","q":"Bagaimana jika karakter yang menyerang diganti, atau ditukar (swap)?","a":"<ul><li>Jika <strong>penyerangnya<\/strong> diganti dengan karakter lain (bukan lewat swap), serangan pertama berakhir dan karakter baru menyatakan serangan baru dari awal.<\/li><li><strong>Swap<\/strong> berbeda: kartu yang masuk lewat swap mengambil alih status kartu yang ditukarnya, termasuk \"sudah menyerang\" dan \"sedang menyerang\". Target serangan tetap sama, jadi tidak ada ganti target.<\/li><\/ul>","src":"CR 301.18.b–c, 303.2.a.4.3.2.6. Head Judge of Marvel Hero Rush Indonesia, 13 dan 23 Okt 2026."},{"id":"F-20","q":"Apakah karakter yang serangannya gagal dihitung \"tidak menyerang\"?","a":"<p>Tidak. Karakter yang sudah <strong>menyatakan<\/strong> serangan dihitung sudah menyerang, walaupun serangannya di-counter, kehilangan target, atau berakhir lebih awal. Hanya karakter yang sama sekali tidak menyatakan serangan yang dihitung \"tidak menyerang\". Ini penting untuk kartu seperti Loki 「God of Story」.<\/p>","src":"CR 303.2.a.4.5. Head Judge of Marvel Hero Rush Indonesia, 18 Agu, 6 Okt dan 17 Okt 2026."},{"id":"F-21","q":"Bagaimana cara kerja AIR STRIKE? Bisakah serangannya dibelokkan?","a":"<ul><li>Karakter dengan AIR STRIKE boleh menyerang area BATTLE tempat karakter lawan berada <strong>seolah-olah area itu Weakness<\/strong>. Karakter itu juga boleh memilih menyerang karakter seperti biasa.<\/li><li>Serangannya tetap bisa <strong>dibelokkan<\/strong>, misalnya oleh karakter dengan <strong>BLOCK<\/strong> atau oleh <a class=\"nw-chip rf-chip\" href=\"#c=BP01-067\" data-card=\"BP01-067\"><b>BP01-067<\/b><\/a> 「Hostile Focus」 Winter Soldier. Penyerang lalu harus bertarung dengan target baru.<\/li><li>Rulebook menyebut kemampuan ini <strong>AIR-ATTACK<\/strong>; di kartu tercetak <strong>AIR STRIKE<\/strong>. Keduanya kemampuan yang sama.<\/li><\/ul>","src":"CR 305.5.a, 305.2.a. Head Judge of Marvel Hero Rush Indonesia, 2–3 Sep 2026."},{"id":"F-22","q":"Karakter keluar dari FIELD lalu kembali pada giliran yang sama. Bolehkah ia menyerang lagi?","a":"<p>Boleh, jika ia kembali ke BATTLE Anda dan urutan serangan (FRONT → WING → BACK) belum melewati areanya. Kartu yang keluar dari FIELD menjadi <strong>kartu baru<\/strong>, jadi kesempatan menyerangnya dan efek ONCE PER TURN-nya kembali baru.<\/p>","src":"CR 301.45.b, 303.2.a.4.4. Head Judge of Marvel Hero Rush Indonesia, 12 Agu, 20 Sep dan 22 Sep 2026."}]},{"t":"Counter Step dan Counter Phase","items":[{"id":"F-23","q":"Bagaimana cara kerja Counter Step? Bolehkah melakukan counter lebih dari sekali?","a":"<ul><li>Di Counter Step setiap pertarungan, pemain <strong>bergantian, satu aksi setiap kali<\/strong>, dimulai dari <strong>lawan<\/strong> pemain yang sedang mendapat giliran.<\/li><li>Aksi yang bisa dipilih: COUNTER CALL, mengaktifkan efek COUNTER·ACTI, atau pass (tidak melakukan aksi).<\/li><li>Anda boleh beraksi lagi pada kesempatan Anda berikutnya. Step ini baru berakhir jika <strong>kedua pemain pass berturut-turut<\/strong>.<\/li><li>Counter Phase (setelah Battle Phase) berjalan dengan cara yang sama.<\/li><\/ul><p><strong>Contoh satu pertarungan<\/strong> (Pemain A adalah pemain yang sedang mendapat giliran; <em>counter<\/em> = melakukan COUNTER CALL atau mengaktifkan efek COUNTER·ACTI, <em>tidak counter<\/em> = pass):<\/p><ol><li>Pemain A menyerang.<\/li><li>Pemain B: tidak counter.<\/li><li>Pemain A: counter.<\/li><li>Pemain B: counter.<\/li><li>Pemain A: counter.<\/li><li>Pemain B: tidak counter.<\/li><li>Pemain A: tidak counter.<\/li><li>Kedua pemain pass berturut-turut (langkah 6 dan 7), jadi Counter Step berakhir dan hasil pertarungan ditentukan.<\/li><\/ol><p>Pass Pemain B di langkah 2 belum mengakhiri step ini, karena Pemain A tidak langsung pass setelahnya. Ingat, setiap pemain hanya boleh melakukan satu COUNTER CALL di Battle Phase (<a href=\"#faq/id/F-24\">F-24<\/a>), jadi dua counter Pemain A di contoh ini tidak boleh dua-duanya COUNTER CALL.<\/p>","src":"CR 303.2.a.4.3.2.1–303.2.a.4.3.2.4, 303.2.a.5.1–303.2.a.5.3. Aturan ini menggantikan aturan lama \"masing-masing satu aksi\"; diumumkan oleh Head Judge of Marvel Hero Rush Indonesia pada 24 Sep 2026."},{"id":"F-24","q":"Berapa kali saya boleh melakukan COUNTER CALL per giliran?","a":"<p>Setiap pemain boleh melakukan COUNTER CALL:<\/p><ul><li><strong>sekali di Battle Phase<\/strong>, berapa pun jumlah pertarungannya (Counter Step), dan<\/li><li><strong>sekali di Counter Phase<\/strong>.<\/li><\/ul>","src":"CR 303.2.a.4.3.2.3.1.1, 303.2.a.5.2.1.1. Head Judge of Marvel Hero Rush Indonesia, 16 Agu 2026."},{"id":"F-25","q":"Apakah COUNTER CALL sama dengan CALL biasa? Apakah COUNTER CALL karakter Lv4+ tetap butuh biaya?","a":"<p>Ya. COUNTER CALL mengikuti aturan CALL biasa, jadi karakter Lv4+ tetap butuh biaya retreat. Hanya kartu yang punya kemampuan <strong>COUNTER<\/strong> yang bisa dipanggil lewat COUNTER CALL.<\/p>","src":"CR 301.19.f, 305.1.a. Head Judge of Marvel Hero Rush Indonesia, 31 Agu 2026."},{"id":"F-26","q":"Kapan efek ACTI dan COUNTER·ACTI boleh dipakai?","a":"<ul><li><strong>ACTI:<\/strong> hanya di <strong>Action Phase Anda sendiri<\/strong>.<\/li><li><strong>COUNTER·ACTI:<\/strong> di Action Phase Anda sendiri, di <strong>Counter Phase pemain mana pun<\/strong>, dan di <strong>Counter Step<\/strong>.<\/li><\/ul>","src":"CR 201.10.f.2–201.10.f.3."}]},{"t":"Efek dan timing","items":[{"id":"F-27","q":"Apakah ada chain atau stack?","a":"<p>Tidak. Efek <strong>langsung diselesaikan begitu terpicu atau diaktifkan<\/strong>. Jika beberapa efek terpicu bersamaan, efek-efek itu menunggu dan diselesaikan satu per satu:<\/p><ul><li>jika semuanya milik satu pemain, pemain itu yang menentukan urutannya;<\/li><li>jika kedua pemain punya efek, <strong>pemain yang sedang mendapat giliran mengurutkan dan menyelesaikan efeknya lebih dulu<\/strong>, baru kemudian lawan.<\/li><\/ul>","src":"CR 304.1.c, 304.1.e–g, 304.2.a. Head Judge of Marvel Hero Rush Indonesia, 13 Agu, 20 Sep dan 22 Okt 2026."},{"id":"F-28","q":"Bagaimana jika efek baru terpicu saat efek lain sedang diselesaikan?","a":"<ul><li>Selesaikan dulu efek yang sedang berjalan, lalu selesaikan trigger baru (turunan) itu <strong>saat itu juga<\/strong>, sebelum efek-efek yang sudah menunggu sebelumnya.<\/li><li>Jika trigger-trigger baru milik satu pemain membentuk satu kelompok, tidak ada yang boleh disisipkan di tengah kelompok itu. Jika pemain yang sama masih punya trigger lama yang menunggu, pemain itu memilih apakah trigger lama itu diselesaikan sebelum atau sesudah seluruh kelompok baru.<\/li><\/ul><p>Contoh: 「Antimatter」 Iron Man milik Pemain A mem-Prune Gwen milik Pemain B, sementara Pym Arrow milik B (terpicu oleh CALL Antimatter) masih menunggu. B boleh menyelesaikan Pym dulu lalu Gwen + Silk, atau Gwen + Silk dulu lalu Pym, tetapi tidak boleh Gwen → Pym → Silk.<\/p>","src":"CR 304.1.h, 304.1.f. Head Judge of Marvel Hero Rush Indonesia, 22 Okt 2026."},{"id":"F-29","q":"Apakah saya wajib memakai setiap efek? Bagaimana jika hanya sebagian yang bisa dilakukan?","a":"<ul><li>Efek yang memakai kata <strong>\"may\"<\/strong> di teks Inggris bersifat pilihan. Tanpa \"may\", efeknya <strong>wajib<\/strong>. Teks kartu Indonesia tidak selalu menulis \"bisa/dapat\" untuk \"may\", jadi cek teks Inggrisnya (lihat F-41).<\/li><li>Begitu efek mulai diselesaikan, lakukan <strong>sebanyak mungkin<\/strong> bagian efek itu.<\/li><li>Teks setelah <strong>\"after doing so\"<\/strong> (istilah di CR) hanya terjadi jika semua bagian sebelumnya sudah dilakukan sepenuhnya.<\/li><li>\"Up to X\" (sampai X) membolehkan Anda memilih 0; memilih 0 dihitung sebagai efek tidak diselesaikan.<\/li><\/ul>","src":"CR 304.1.a–b, 304.1.d, 301.38.a, 301.34.a–b. Head Judge of Marvel Hero Rush Indonesia, 20 Sep 2026."},{"id":"F-30","q":"Bolehkah saya memakai efek jika hasilnya tidak punya target yang sah?","a":"<p>Boleh, jika bagian pertamanya bisa dilakukan. Bagian pertama (misalnya membuang atau mem-Prune kartunya) tetap terjadi, dan hasilnya tidak berefek apa-apa. Contoh:<\/p><ul><li>Membuang <a class=\"nw-chip rf-chip\" href=\"#c=SD01-006\" data-card=\"SD01-006\"><b>SD01-006<\/b><\/a> 「Hourglass Bite」 Black Widow dari tangan saat lawan tidak punya karakter yang memenuhi syarat.<\/li><li><a class=\"nw-chip rf-chip\" href=\"#c=SP01-006\" data-card=\"SP01-006\"><b>SP01-006<\/b><\/a> 「Spider-Archenemy」 Red Goblin: Anda mem-Prune Red Goblin dan 1 karakter lain atau kartu terpasang di FIELD Anda, dan X adalah total Lv kartu yang Anda Prune. Anda boleh melakukannya walaupun lawan <strong>tidak punya karakter dengan Lv tepat X<\/strong> di BATTLE. Kedua kartu Anda tetap di-Prune, dan tidak terjadi apa-apa pada lawan.<\/li><\/ul>","src":"Head Judge of Marvel Hero Rush Indonesia, 25 Okt 2026 (beliau menyebut mungkin keliru; jawaban ini akan diperbarui jika ada ruling resmi yang berbeda)."},{"id":"F-31","q":"Saya menarik kartu saat efek sedang diselesaikan. Apakah trigger dari tangan pada kartu itu masih bisa dipakai?","a":"<p>Bisa. Jika isi tangan Anda berubah saat efek-efek dari satu timing sedang diselesaikan, dan kartu baru itu punya trigger untuk timing yang sama, kartu itu dianggap terpicu pada timing tersebut.<\/p><p>Contoh:<\/p><ol><li>Lawan punya <a class=\"nw-chip rf-chip\" href=\"#c=SD03-011\" data-card=\"SD03-011\"><b>SD03-011<\/b><\/a> 「Ancestral Plane」 New Black Panther di WING. Efek AUTO-nya memberi karakter Anda di FRONT Power -500.<\/li><li>Anda memanggil <a class=\"nw-chip rf-chip\" href=\"#c=BP01-077\" data-card=\"BP01-077\"><b>BP01-077<\/b><\/a> 「I Need You」 Captain America ke FRONT Anda. Kartu itu masuk ke FIELD, dan pada saat yang sama Power-nya berkurang karena Ancestral Plane.<\/li><li>Trigger I Need You diselesaikan: Anda menarik 1 kartu, yaitu <a class=\"nw-chip rf-chip\" href=\"#c=BP01-063\" data-card=\"BP01-063\"><b>BP01-063<\/b><\/a> 「Time Abduction」 Loki (\"Saat Power karakter Anda berkurang\"). Lalu Anda menempatkan kartu teratas Deck Anda secara tertutup ke BASE.<\/li><li>Pengurangan Power itu terjadi pada timing yang sama yang masih sedang diselesaikan, jadi Time Abduction dianggap terpicu. Anda boleh mem-Prune kartu itu dari tangan dan memakai efeknya.<\/li><\/ol>","src":"CR 304.1.k. Head Judge of Marvel Hero Rush Indonesia, 21 Okt 2026."},{"id":"F-32","q":"Apa yang terjadi di End Phase, dan bagaimana urutannya?","a":"<ol><li>Efek yang terpicu \"saat giliran berakhir\" terpicu dan diselesaikan.<\/li><li>Efek yang berlaku \"pada giliran ini\" berakhir.<\/li><li>Pemain yang sedang mendapat giliran membuang kartu di tangan sampai tersisa 9 kartu.<\/li><\/ol>","src":"CR 303.2.a.6.1.1–303.2.a.6.1.3. Head Judge of Marvel Hero Rush Indonesia, 4 Okt 2026."}]},{"t":"Power, R, dan keluar dari FIELD","items":[{"id":"F-33","q":"Apakah karakter dengan Power 0 langsung di-retreat?","a":"<p>Ya. Begitu efek menurunkan Power karakter menjadi 0, hasilnya langsung terkunci: karakter itu harus di-retreat.<\/p>","src":"CR 301.16.a.1, 301.16.b. Head Judge of Marvel Hero Rush Indonesia, 31 Okt 2026."},{"id":"F-34","q":"\"Menjadi X\" vs \"+X / -X\": mana yang berlaku?","a":"<p><strong>Perubahan<\/strong> (change, misalnya \"R menjadi 3\", \"Lv menjadi 6\") menggantikan penambahan dan pengurangan sebelumnya. Penambahan atau pengurangan yang datang <strong>setelah<\/strong> perubahan itu dihitung di atas nilai yang baru. Jika ada dua perubahan, yang lebih baru yang berlaku; jika yang lebih baru berakhir, perubahan sebelumnya berlaku lagi. Rincian lengkapnya ada di CR 301.41.<\/p><p>Contoh:<\/p><ul><li><a class=\"nw-chip rf-chip\" href=\"#c=BP01-097\" data-card=\"BP01-097\"><b>BP01-097<\/b><\/a> 「Original Mutant」 Namor ada di BATTLE Anda: R karakter Anda di FRONT <strong>menjadi 3<\/strong>. Jika karakter itu lalu mendapat R+1 (misalnya dari <a class=\"nw-chip rf-chip\" href=\"#c=BP01-117\" data-card=\"BP01-117\"><b>BP01-117<\/b><\/a> 「Ancestral Blessing」 New Black Panther), R-nya menjadi <strong>4<\/strong>: +1 ditambahkan di atas perubahan.<\/li><li><a class=\"nw-chip rf-chip\" href=\"#c=SD04-001\" data-card=\"SD04-001\"><b>SD04-001<\/b><\/a> 「God of Trick」 Loki terpasang pada sebuah karakter: R karakter itu <strong>menjadi 0<\/strong> dan ia mendapat Power +1000. R+X yang sebelumnya dimiliki karakter itu hilang. Power +1000 adalah penambahan, jadi ditambahkan seperti biasa.<\/li><li>Pemain yang mengendalikan karakter itu punya Namor di BATTLE, dan karakter itu ada di FRONT. Sekarang ada dua perubahan: dari Loki (R menjadi 0) dan dari Namor (R menjadi 3). Yang <strong>mulai berlaku belakangan<\/strong> yang menang. Jika Loki dipasang setelah Namor sudah ada, R-nya 0; jika Namor datang belakangan, R-nya 3, dan jika Namor kemudian pergi, perubahan dari Loki berlaku lagi (R 0).<\/li><\/ul>","src":"CR 301.41.a–k (terutama 301.41.d dan 301.41.f). Head Judge of Marvel Hero Rush Indonesia, 26 Agu dan 24 Sep 2026."},{"id":"F-35","q":"Apa yang dihitung sebagai \"Power berkurang\" (untuk kartu seperti 「Time Abduction」 Loki)?","a":"<p>Setiap efek yang memberi karakter <strong>Power -X<\/strong> dihitung, termasuk efek dari kartu Anda sendiri. Buff yang berakhir <strong>tidak<\/strong> dihitung sebagai pengurangan.<\/p>","src":"Head Judge of Marvel Hero Rush Indonesia, 29 Agu, 24 Sep dan 6 Okt 2026."},{"id":"F-36","q":"Apa bedanya RETREAT, retreat, buang (discard), dan Prune?","a":"<ul><li><strong>RETREAT<\/strong> (huruf besar) adalah area. <strong>retreat<\/strong> (huruf kecil) adalah aksinya. Ini cara penulisan di teks kartu bahasa Inggris; di teks kartu Indonesia aksinya kadang juga ditulis dengan huruf besar (misalnya \"RETREAT 1 karakter\"), jadi lihat konteks kalimatnya.<\/li><li>Hanya kartu <strong>di FIELD<\/strong> yang bisa di-retreat. Memindahkan kartu dari tangan atau Deck ke RETREAT disebut <strong>buang (discard)<\/strong>.<\/li><li><strong>Prune<\/strong> memindahkan kartu ke <strong>VOID<\/strong>.<\/li><li>\"Jumlah kartu yang Anda retreat\" hanya menghitung kartu yang Anda retreat (misalnya sebagai biaya CALL), bukan kartu terpasang yang ikut terbawa. \"Kartu yang masuk ke RETREAT\" menghitung setiap kartu yang masuk ke RETREAT.<\/li><\/ul>","src":"CR 301.15, 301.16, 301.17.a, 302.8.a. Head Judge of Marvel Hero Rush Indonesia, 26 Agu dan 10 Okt 2026."}]},{"t":"Kartu terpasang dan swap","items":[{"id":"F-37","q":"Apa yang terjadi pada kartu terpasang (Attached Card)?","a":"<ul><li>Kartu terpasang <strong>bukan karakter<\/strong>: tidak bisa di-retreat untuk membayar biaya CALL dan tidak dihitung sebagai karakter di BATTLE.<\/li><li>Kartu terpasang <strong>tetap punya efeknya sendiri<\/strong>.<\/li><li>Kartu terpasang <strong>ikut<\/strong> karakternya ke RETREAT, ke tangan, atau ke Deck, dan selalu kembali ke <strong>pemiliknya<\/strong>.<\/li><li>Jika karakternya tidak lagi menjadi karakter (misalnya dibalik menjadi kartu tertutup), kartu-kartu yang terpasang masuk ke RETREAT.<\/li><li>Kartu terpasang tidak bisa dipasang lagi ke karakter yang sama, dan urutan kartu terpasang tidak bisa diubah.<\/li><\/ul>","src":"CR 301.25.a–c, 301.25.d–l, 301.25.b, 301.25.n, 301.3. Head Judge of Marvel Hero Rush Indonesia, 17 Agu, 28 Agu, 5 dan 16 Sep, 4 dan 26 Okt 2026."},{"id":"F-38","q":"Lawan memasang Riot ke karakter saya dan efek Riot membuat karakter itu di-retreat. Bolehkah saya memakai 「Turn The Tide」?","a":"<p>Tidak. Setelah terpasang, Riot berada pada karakter <strong>Anda<\/strong>, jadi retreat itu berasal dari efek di pihak Anda sendiri, bukan dari \"efek kartu lawan\".<\/p>","src":"Head Judge of Marvel Hero Rush Indonesia, 25 Okt 2026."},{"id":"F-43","q":"Bisakah 「Turn The Tide」 Captain America mengembalikan karakter yang di-retreat karena Power-nya menjadi 0?","a":"<p>Bisa. Jika <strong>efek kartu lawan<\/strong> membuat Power karakter Anda yang Lv4 atau lebih rendah (dengan trait [Human]) menjadi 0, karakter itu di-retreat oleh aturan permainan, dan ini dihitung sebagai masuk ke RETREAT dari BATTLE karena efek kartu lawan. Anda boleh memakai <a class=\"nw-chip rf-chip\" href=\"#c=BP01-066\" data-card=\"BP01-066\"><b>BP01-066<\/b><\/a> / <a class=\"nw-chip rf-chip\" href=\"#c=EB01-012\" data-card=\"EB01-012\"><b>EB01-012<\/b><\/a> 「Turn The Tide」 Captain America.<\/p>","src":"CR 301.16.a.1, 301.16.b. Dikonfirmasi oleh Head Judge of Marvel Hero Rush Indonesia (Nov 2026)."},{"id":"F-39","q":"Apa saja yang ditukar oleh swap?","a":"<p>Kedua kartu bertukar <strong>posisi<\/strong>, <strong>status saat ini<\/strong> (misalnya \"sudah menyerang\", buff dan debuff dari efek), dan <strong>kartu terpasangnya<\/strong>. Bonus yang berasal dari efek AUTO milik kartu itu sendiri tetap melekat pada kartu tersebut.<\/p>","src":"CR 301.18.a–c. Head Judge of Marvel Hero Rush Indonesia, 23 Okt 2026."},{"id":"F-40","q":"Apa saja yang hilang karena \"kehilangan efek\" (misalnya Anti-Venom)?","a":"<p>Kartu itu kehilangan <strong>semua<\/strong> jenis efek, teks efek, dan kemampuannya, termasuk kemampuan seperti AIR STRIKE, dan juga efek apa pun yang akan didapatnya kemudian. <strong>UNIQUE adalah pengecualian<\/strong>: UNIQUE tidak bisa hilang. Efek dari kartu <strong>lain<\/strong> yang sedang berlaku padanya (misalnya -2000) tetap berlaku.<\/p>","src":"CR 301.33.a, 305.6.a. Head Judge of Marvel Hero Rush Indonesia, 29 Sep dan 7 Okt 2026."}]},{"t":"Teks kartu","items":[{"id":"F-41","q":"Teks bahasa Indonesia dan bahasa Inggris pada kartu berbeda. Mana yang diikuti?","a":"<p>Ikuti teks <strong>bahasa Inggris<\/strong> sampai errata bahasa Indonesia diterbitkan. Teks bahasa Inggris diterjemahkan langsung dari teks asli bahasa Mandarin, sedangkan teks bahasa Indonesia diterjemahkan lewat bahasa Inggris lebih dulu. Lihat <strong>Errata &amp; Text Differences<\/strong> untuk kasus yang sudah diketahui.<\/p>","src":"Head Judge of Marvel Hero Rush Indonesia, 16 Agu 2026."},{"id":"F-42","q":"Bolehkah saya memakai kartu berbahasa Inggris di turnamen Indonesia?","a":"<p>Tidak. <strong>Kartu<\/strong> berbahasa Inggris tidak legal di turnamen Indonesia. <strong>Rush Point<\/strong> berbahasa Inggris boleh dipakai.<\/p>","src":"Head Judge of Marvel Hero Rush Indonesia, 13 Agu 2026."},{"id":"F-44","q":"Apa bedanya \"karakter\" dan \"kartu\" dalam teks kartu?","a":"<p>Keduanya <strong>tidak<\/strong> sama, jadi baca teks kartu dengan teliti.<\/p><ul><li><strong>Kartu<\/strong> berarti kartu apa saja: karakter, kartu tertutup, atau kartu terpasang.<\/li><li><strong>Karakter<\/strong> hanya berarti karakter yang terbuka. Setiap kartu di Deck Anda adalah karakter, tetapi di FIELD sebuah kartu bisa berhenti menjadi karakter:<ul><li><strong>kartu tertutup<\/strong> di BASE adalah kartu, bukan karakter (kembali menjadi karakter saat dibalik terbuka);<\/li><li><strong>kartu terpasang<\/strong> adalah kartu, bukan karakter (kembali menjadi karakter saat dilepas).<\/li><\/ul><\/li><li>Jadi efek yang berbunyi \"<strong>1 karakter Anda<\/strong>\" (\"1 of your characters\") tidak bisa memilih kartu tertutup atau kartu terpasang, sedangkan efek yang berbunyi \"<strong>1 kartu Anda<\/strong>\" (\"1 of your cards\") bisa.<\/li><\/ul><p>Contoh:<\/p><ul><li><a class=\"nw-chip rf-chip\" href=\"#c=BP01-061\" data-card=\"BP01-061\"><b>BP01-061<\/b><\/a> 「Follow Shadow」 New Black Panther: \"RETREAT 2 <strong>kartu<\/strong> milik Anda di BASE\" → karakter terbuka dan kartu tertutup sama-sama dihitung.<\/li><li><a class=\"nw-chip rf-chip\" href=\"#c=SP01-026\" data-card=\"SP01-026\"><b>SP01-026<\/b><\/a> 「Vigil of Love」 Amazing Spider-Man: \"Tukar kartu ini dari tangan dengan 1 <strong>kartu<\/strong> Anda di FIELD yang memiliki nama [Ghost-Spider] atau [Gwen]…\" → bisa juga ditukar dengan Gwen yang berupa kartu terpasang.<\/li><li>Biaya CALL me-retreat <strong>karakter<\/strong> (kartu tertutup diperbolehkan oleh aturan khusus dan dihitung Lv1), jadi kartu terpasang tidak pernah bisa menjadi bagian dari biaya CALL.<\/li><\/ul>","src":"CR 201.1–201.2, 301.21.a–b, 301.21.g, 301.22.a, 301.25.a, 301.26.a, 301.19.b."}]}]};

const D = RF_DATA;
/* Poin yang DISEMBUNYIKAN sementara. Isinya tetap ada di RF_DATA; hapus nomornya dari daftar
   ini untuk menampilkannya lagi (link #errata/<no> lalu kembali berfungsi).
   Nomor yang DIHAPUS PERMANEN (jangan dipakai ulang):
   - TD-04 (BP01-035 Hulk Buster) — dihapus 3 Nov 2026 setelah konfirmasi ulang pemilik: "BATTLE Move" di
     kartu memang benar (perpindahan antar area BATTLE: FRONT/WING/BACK, CR 301.23), bukan BATTLE-BASE MOVE. */
const HIDDEN = [];
D.err.forEach(p=>p.groups.forEach(g=>{ g.items = g.items.filter(i=>!HIDDEN.includes(i.id)); }));
D.faq.forEach(s=>{ s.items = s.items.filter(i=>!HIDDEN.includes(i.id)); });
RF_FAQ_ID.sections.forEach(s=>{ s.items = s.items.filter(i=>!HIDDEN.includes(i.id)); });
const FAQ_IDS = D.faq.reduce((a,s)=>a.concat(s.items.map(i=>i.id)), []);
const ERR_IDS = D.err.reduce((a,p)=>a.concat(...p.groups.map(g=>g.items.map(i=>i.id))), []);
/* versi Indonesia hanya dipakai kalau nomor & urutannya sama persis dengan versi Inggris */
const FAQ_ID_OK = (()=>{ const ids = RF_FAQ_ID.sections.reduce((a,s)=>a.concat(s.items.map(i=>i.id)), []);
  const ok = ids.length === FAQ_IDS.length && ids.every((x,i)=>x === FAQ_IDS[i]);
  if(!ok) console.warn('[rules-faq] nomor FAQ versi Indonesia tidak sama dengan versi Inggris — versi ID dimatikan');
  return ok; })();

/* ---------------- bahasa Rules FAQ (v7.26) ---------------- */
const LANG_KEY = 'mhr-faq-lang';
let faqLang = 'en';
try{ if(FAQ_ID_OK && localStorage.getItem(LANG_KEY) === 'id') faqLang = 'id'; }catch(e){}
function setLang(l){
  faqLang = (l === 'id' && FAQ_ID_OK) ? 'id' : 'en';
  try{ localStorage.setItem(LANG_KEY, faqLang); }catch(e){}
}
const UI = {
  en: { search:'Search the FAQ…', open:'Expand all', close:'Collapse all', empty:'No answers match your search.',
        src:'Source:', copy:'🔗 Copy link', copied:'✓ Link copied', copyTitle:'Copy a link to ', prompt:'Copy this link:',
        nav:'FAQ sections', gloss:'',
        foot:'Also see <a href="#errata">Errata &amp; Text Differences</a> and the full <a href="#rules">Official Rules 1.03</a>.' },
  id: { search:'Cari di FAQ…', open:'Buka semua', close:'Tutup semua', empty:'Tidak ada jawaban yang cocok dengan pencarian Anda.',
        src:'Sumber:', copy:'🔗 Salin link', copied:'✓ Link tersalin', copyTitle:'Salin link ke ', prompt:'Salin link ini:',
        nav:'Bagian FAQ', gloss:'📖 Istilah yang dipakai',
        foot:'Lihat juga <a href="#errata">Errata &amp; Text Differences</a> dan <a href="#rules">Official Rules 1.03</a> lengkap (keduanya dalam bahasa Inggris).' }
};
function faqSecs(){ return faqLang === 'id' ? RF_FAQ_ID.sections : D.faq; }
/* '#faq/...' → {lang, focus}. Bagian yang dikenali: 'en' / 'id' lalu nomor poin. */
function parseFaqSub(sub){
  const parts = String(sub || '').split('/').filter(Boolean);
  let lang = null, focus = null;
  if(parts[0] && /^(en|id)$/i.test(parts[0])) lang = parts.shift().toLowerCase();
  if(parts[0] && FAQ_IDS.includes(parts[0].toUpperCase())) focus = parts[0].toUpperCase();
  return { lang, focus };
}
function faqHash(focus){ return '#faq' + (faqLang === 'id' ? '/id' : '') + (focus ? '/' + focus : ''); }

function linkFor(kind, id){
  /* Rules FAQ: bahasa selalu ikut di link supaya penerima melihat bahasa yang sama */
  return location.origin + location.pathname + '#' + kind + '/' + (kind === 'faq' ? faqLang + '/' : '') + id;
}
function copyText(txt){
  if(navigator.clipboard && window.isSecureContext){
    return navigator.clipboard.writeText(txt);
  }
  return new Promise((res, rej)=>{
    try{
      const ta = document.createElement('textarea');
      ta.value = txt; ta.setAttribute('readonly',''); ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      const ok = document.execCommand('copy'); ta.remove();
      ok ? res() : rej(new Error('copy failed'));
    }catch(e){ rej(e); }
  });
}
function copyBtn(kind, id){
  const u = UI[kind === 'faq' ? faqLang : 'en'];
  return `<button type="button" class="rf-copy" data-rfcopy="${kind}/${id}" title="${u.copyTitle}${id}">${u.copy}</button>`;
}
/* gambar kecil kartu di halaman Errata: errata teks Indonesia (V.1, E-12, E-14) memakai
   printing Indonesia (images/), errata teks Inggris (E-13) memakai images/en/, sisanya
   mengikuti bahasa kartu yang sedang dipakai situs (artFile). */
function thumbSrc(id, no){
  if(id === 'E-13') return 'images/en/' + no + '.jpg';
  if(id.startsWith('E-')) return 'images/' + no + '.jpg';
  return (typeof artFile === 'function') ? artFile(no) : 'images/' + no + '.jpg';
}

/* ---------------- Rules FAQ ---------------- */
function renderFaq(wrap, focusId){
  const u = UI[faqLang], secsData = faqSecs();
  const nav = secsData.map((s,i)=>`<a href="#faq" data-rfsec="${i}">${s.t}</a>`).join('');
  const secs = secsData.map((s,i)=>`
    <section class="rf-sec" id="rf-sec-${i}" data-rfsec-box="${i}">
      <h3>${s.t}</h3>
      ${s.items.map(it=>`
      <details class="rf-item" id="faq-${it.id}" data-rfid="${it.id}">
        <summary><span class="rf-id">${it.id}</span><span class="rf-q">${it.q}</span></summary>
        <div class="rf-a">
          ${it.a}
          ${it.src ? `<p class="rf-src">${u.src} ${it.src}</p>` : ''}
          <div class="rf-acts">${copyBtn('faq', it.id)}</div>
        </div>
      </details>`).join('')}
    </section>`).join('');
  const langBtns = FAQ_ID_OK ? `
      <div class="rf-lang" role="group" aria-label="Language / Bahasa">
        <button type="button" data-rflang="en" aria-pressed="${faqLang === 'en'}">English</button>
        <button type="button" data-rflang="id" aria-pressed="${faqLang === 'id'}">Bahasa Indonesia</button>
      </div>` : '';
  wrap.innerHTML = `
    <div class="rf-wrap rf-faq" lang="${faqLang}">
      ${langBtns}
      <h2 class="rf-h">❓ Rules FAQ</h2>
      <div class="rf-intro">${faqLang === 'id' ? RF_FAQ_ID.intro : D.faqIntro}</div>
      ${faqLang === 'id' ? `<details class="rf-gloss"><summary>${u.gloss}</summary>${RF_FAQ_ID.gloss}</details>` : ''}
      <div class="rf-tools">
        <input type="search" class="rf-search" id="rfSearch" placeholder="${u.search}" aria-label="${u.search}">
        <button type="button" class="rf-tbtn" data-rfall="open">${u.open}</button>
        <button type="button" class="rf-tbtn" data-rfall="close">${u.close}</button>
      </div>
      <nav class="rf-jump" aria-label="${u.nav}">${nav}</nav>
      <p class="rf-empty" id="rfEmpty" hidden>${u.empty}</p>
      ${secs}
      <p class="rf-foot">${u.foot}</p>
    </div>`;
  const inp = wrap.querySelector('#rfSearch');
  inp.addEventListener('input', ()=>filterFaq(wrap, inp.value));
  if(focusId) focusItem(wrap, 'faq-' + focusId);
}
function plain(html){ const d = document.createElement('div'); d.innerHTML = html; return (d.textContent || '').toLowerCase(); }
const faqIndex = {};
function filterFaq(wrap, q){
  if(!faqIndex[faqLang]){ const ix = faqIndex[faqLang] = {};
    faqSecs().forEach(s=>s.items.forEach(it=>{ ix[it.id] = plain(it.id + ' ' + it.q + ' ' + it.a + ' ' + it.src); })); }
  const ix = faqIndex[faqLang];
  const words = q.toLowerCase().trim().split(/\s+/).filter(Boolean);
  let shown = 0;
  wrap.querySelectorAll('.rf-item').forEach(el=>{
    const ok = !words.length || words.every(w=>ix[el.dataset.rfid].includes(w));
    el.hidden = !ok; if(ok) shown++;
    if(words.length) el.open = ok;
  });
  wrap.querySelectorAll('[data-rfsec-box]').forEach(sec=>{
    sec.hidden = ![...sec.querySelectorAll('.rf-item')].some(x=>!x.hidden);
  });
  const e = wrap.querySelector('#rfEmpty'); if(e) e.hidden = shown > 0;
}

/* ---------------- Errata & Text Differences ---------------- */
function renderErrata(wrap, focusId){
  const parts = D.err.map(p=>`
    <section class="rf-sec">
      <h3>${p.t}</h3>
      ${p.intro || ''}
      ${p.groups.map(g=>`
        ${g.t ? `<h4 class="rf-gh">${g.t}</h4>` : ''}
        ${g.intro ? `<div class="rf-gi">${g.intro}</div>` : ''}
        <div class="rf-list">
        ${g.items.map(it=>`
          <article class="rf-er" id="errata-${it.id}" data-rfid="${it.id}">
            ${it.cards.length ? `<div class="rf-thumbs">${it.cards.map(no=>
              `<button type="button" class="rf-thumb" data-card="${no}" title="Open ${no}">
                 <img src="${thumbSrc(it.id, no)}" alt="${no}" loading="lazy" decoding="async" onerror="this.parentNode.hidden=true">
               </button>`).join('')}</div>` : ''}
            <div class="rf-er-body">
              <div class="rf-er-h"><span class="rf-id">${it.id}</span> <span class="rf-er-t">${it.t}</span></div>
              ${it.a}
              <div class="rf-acts">${copyBtn('errata', it.id)}</div>
            </div>
          </article>`).join('')}
        </div>`).join('')}
    </section>`).join('');
  wrap.innerHTML = `
    <div class="rf-wrap rf-errata">
      <h2 class="rf-h">⚠️ Errata &amp; Text Differences</h2>
      <div class="rf-intro">${D.errIntro}</div>
      ${parts}
      <p class="rf-foot">Questions about how a card works? See the <a href="#faq">Rules FAQ</a>.</p>
    </div>`;
  if(focusId) focusItem(wrap, 'errata-' + focusId);
}

function focusItem(wrap, elId){
  const el = wrap.querySelector('#' + CSS.escape(elId));
  if(!el) return;
  if(el.tagName === 'DETAILS') el.open = true;
  el.classList.add('rf-hit');
  setTimeout(()=>{ el.scrollIntoView({block:'start', behavior:'smooth'}); }, 60);
  setTimeout(()=>el.classList.remove('rf-hit'), 2600);
}

/* satu listener untuk kedua halaman (dipasang ke #panduanWrap oleh index.html) */
function onClick(e, wrap){
  const cp = e.target.closest('[data-rfcopy]');
  if(cp){
    const [kind, id] = cp.dataset.rfcopy.split('/');
    const url = linkFor(kind, id), u = UI[kind === 'faq' ? faqLang : 'en'];
    copyText(url).then(()=>{ cp.textContent = u.copied; },
                       ()=>{ window.prompt(u.prompt, url); })
      .finally(()=>setTimeout(()=>{ cp.textContent = u.copy; }, 1800));
    return true;
  }
  const lb = e.target.closest('[data-rflang]');
  if(lb){
    if(lb.dataset.rflang !== faqLang){
      const openIds = [...wrap.querySelectorAll('.rf-item[open]')].map(d=>d.dataset.rfid);
      setLang(lb.dataset.rflang);
      renderFaq(wrap);
      openIds.forEach(id=>{ const d = wrap.querySelector('#faq-' + CSS.escape(id)); if(d) d.open = true; });
      try{ history.replaceState(null, '', faqHash()); }catch(err){}
    }
    return true;
  }
  const card = e.target.closest('[data-card]');
  if(card && typeof openLightbox === 'function' && typeof DB !== 'undefined' && DB.some(d=>d.no === card.dataset.card)){
    e.preventDefault(); openLightbox(card.dataset.card); return true;
  }
  const sec = e.target.closest('[data-rfsec]');
  if(sec){
    e.preventDefault();
    const box = wrap.querySelector('#rf-sec-' + sec.dataset.rfsec);
    if(box) box.scrollIntoView({block:'start', behavior:'smooth'});
    return true;
  }
  const all = e.target.closest('[data-rfall]');
  if(all){
    const open = all.dataset.rfall === 'open';
    wrap.querySelectorAll('.rf-item').forEach(d=>{ if(!d.hidden) d.open = open; });
    return true;
  }
  return false;
}

window.MHRRules = { renderFaq, renderErrata, onClick, FAQ_IDS, ERR_IDS, parseFaqSub, faqHash, setLang,
  getLang: () => faqLang,
  hasId: (kind, id) => (kind === 'faq' ? FAQ_IDS : ERR_IDS).includes(id) };
})();
